// Shared rules used by the browser client and the Node server.
// Pure JS on purpose: no DOM, no three.js, deterministic where it matters.

export const SEA_LIMIT = 1500;
export const MAX_LEVEL = 50;

export const RARITY = {
  common: { label: 'Gewöhnlich', color: '#b9c4c9', power: 1 },
  uncommon: { label: 'Ungewöhnlich', color: '#7fdc8f', power: 1.6 },
  rare: { label: 'Selten', color: '#6fb6ff', power: 2.4 },
  epic: { label: 'Episch', color: '#c08cff', power: 3.4 },
  legendary: { label: 'Legendär', color: '#ffc65c', power: 5 }
};

export function xpForLevel(level) {
  return Math.round(120 * Math.pow(level, 1.55));
}

export function levelFromXp(xp) {
  let level = 1;
  let rest = xp;
  while (level < MAX_LEVEL && rest >= xpForLevel(level)) {
    rest -= xpForLevel(level);
    level += 1;
  }
  return { level, rest, need: xpForLevel(level) };
}

export function clampSea(x, z) {
  const d = Math.hypot(x, z);
  if (d <= SEA_LIMIT) return { x, z };
  const s = SEA_LIMIT / d;
  return { x: x * s, z: z * s };
}

export function dist(ax, az, bx, bz) {
  return Math.hypot(ax - bx, az - bz);
}

export function angleDiff(a, b) {
  let d = (b - a) % (Math.PI * 2);
  if (d > Math.PI) d -= Math.PI * 2;
  if (d < -Math.PI) d += Math.PI * 2;
  return d;
}

// Small deterministic PRNG so loot tables are testable.
export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const LOOT_POOL = [
  { id: 'treibholz', count: [2, 6], weight: 26 },
  { id: 'kanonenkugel', count: [4, 10], weight: 22 },
  { id: 'segeltuch', count: [1, 4], weight: 16 },
  { id: 'rum', count: [1, 2], weight: 14 },
  { id: 'eisenbarren', count: [1, 3], weight: 12 },
  { id: 'koralle', count: [1, 2], weight: 6 },
  { id: 'obsidian', count: [1, 1], weight: 4 },
  { id: 'tempelrelikt', count: [1, 1], weight: 2 },
  { id: 'kartenfragment', count: [1, 1], weight: 1.4 },
  { id: 'urlaubsfrucht', count: [1, 1], weight: 0.6 }
];

export function rollLoot(enemy, rng = Math.random) {
  const rolls = enemy.boss ? 3 : 1;
  const drops = [];
  for (let i = 0; i < rolls; i++) {
    const total = LOOT_POOL.reduce((s, e) => s + e.weight, 0);
    let pick = rng() * total;
    for (const entry of LOOT_POOL) {
      pick -= entry.weight;
      if (pick <= 0) {
        const [lo, hi] = entry.count;
        const count = lo + Math.floor(rng() * (hi - lo + 1));
        const existing = drops.find((d) => d.id === entry.id);
        if (existing) existing.count += count;
        else drops.push({ id: entry.id, count });
        break;
      }
    }
  }
  return {
    drops,
    gold: Math.round((enemy.gold || 20) * (0.8 + rng() * 0.6)),
    xp: Math.round((enemy.xp || 20) * (0.9 + rng() * 0.2))
  };
}

export function cannonDamage(base, skills = {}, fruitPassive = 0) {
  const powder = 1 + 0.07 * (skills.pulverfaust || 0);
  const crit = skills.meisterschuetze ? (Math.random() < 0.12 ? 2 : 1) : 1;
  return Math.round(base * powder * (1 + fruitPassive) * crit);
}

import { clampSea, dist, angleDiff, rollLoot } from './rules.js';

const TAU = Math.PI * 2;

// Server-authoritative sea simulation. The offline client runs the exact same
// code, which keeps singleplayer and multiplayer behaviour identical.
export class SeaSim {
  constructor({ islands, enemies, rng = Math.random, seed = 1337 }) {
    this.islands = islands;
    this.enemyDefs = enemies;
    this.rng = rng;
    this.seed = seed;
    this.npcs = new Map();
    this.loot = new Map();
    this.players = new Map();
    this.events = [];
    this.nextId = 1;
    this.spawnTimer = 0;
    this.elapsed = 0;
    this.spawnInitial();
  }

  id(prefix) {
    return `${prefix}_${this.nextId++}`;
  }

  spawnInitial() {
    const spots = [
      ['marine_patrol', -160, -430], ['marine_patrol', 300, -520], ['marine_patrol', -620, -120],
      ['pirate_raider', -420, 330], ['pirate_raider', 420, 330], ['pirate_raider', -900, 520],
      ['smuggler', -640, -360], ['smuggler', 860, -60], ['smuggler', -1050, -90],
      ['marine_frigate', -250, -720], ['marine_frigate', 250, 900],
      ['ghost_ship', -980, 600], ['ghost_ship', 780, 980],
      ['pirate_raider', 700, 260], ['marine_patrol', 1000, -260]
    ];
    for (const [defId, x, z] of spots) this.spawnNpc(defId, x, z);
    this.spawnNpc('sea_leviathan', 900, 1150, true);
  }

  spawnNpc(defId, x, z, boss = false) {
    const def = this.enemyDefs.find((e) => e.id === defId) || this.enemyDefs[0];
    const npc = {
      id: this.id('npc'),
      defId: def.id,
      name: def.name,
      faction: def.faction,
      boss: Boolean(def.boss || boss),
      ship: def.ship,
      x, z, rot: this.rng() * TAU,
      hp: def.hp, maxHp: def.hp,
      speed: def.speed, turn: def.turn,
      damage: def.damage, range: def.range, aggro: def.aggro,
      xp: def.xp, gold: def.gold,
      patrol: { x, z },
      targetId: null,
      fireCd: 1 + this.rng() * 2,
      state: 'patrol',
      level: def.boss ? 15 : Math.max(1, Math.round(def.hp / 55)),
      alive: true,
      spawnAt: this.elapsed
    };
    this.npcs.set(npc.id, npc);
    this.events.push({ type: 'spawn', npc: this.publicNpc(npc) });
    return npc;
  }

  publicNpc(n) {
    return {
      id: n.id, defId: n.defId, name: n.name, faction: n.faction, boss: n.boss,
      ship: n.ship, x: n.x, z: n.z, rot: n.rot, hp: n.hp, maxHp: n.maxHp,
      level: n.level, state: n.state
    };
  }

  addPlayer(id, { name, faction = 'pirate', x = 0, z = 40, rot = 0, hp = 100, maxHp = 100 }) {
    const p = { id, name, faction, x, z, rot, hp, maxHp, alive: true, hidden: 0, lastHit: 0 };
    this.players.set(id, p);
    return p;
  }

  removePlayer(id) {
    this.players.delete(id);
  }

  setPlayerPos(id, x, z, rot, hp) {
    const p = this.players.get(id);
    if (!p) return;
    const c = clampSea(x, z);
    p.x = c.x; p.z = c.z; p.rot = rot;
    if (typeof hp === 'number') p.hp = Math.max(0, Math.min(p.maxHp, hp));
    p.alive = p.hp > 0;
  }

  player(id) {
    return this.players.get(id) || null;
  }

  tick(dt) {
    dt = Math.min(dt, 0.1);
    this.elapsed += dt;
    this.events.length = 0;

    for (const p of this.players.values()) {
      if (p.hidden > 0) p.hidden = Math.max(0, p.hidden - dt);
      if (!p.alive && this.elapsed - p.lastHit > 6) {
        p.hp = p.maxHp;
        p.alive = true;
        p.x = 0; p.z = 60;
        this.events.push({ type: 'respawn', playerId: p.id, x: p.x, z: p.z });
      }
    }

    for (const npc of this.npcs.values()) {
      if (!npc.alive) {
        if (this.elapsed - npc.sunkAt > 22) this.respawnNpc(npc);
        continue;
      }
      this.stepNpc(npc, dt);
    }

    for (const l of [...this.loot.values()]) {
      l.ttl -= dt;
      l.bob = (l.bob || 0) + dt;
      if (l.ttl <= 0) this.loot.delete(l.id);
    }

    return this.events;
  }

  stepNpc(npc, dt) {
    let target = null;
    let best = Infinity;
    for (const p of this.players.values()) {
      if (!p.alive || p.hidden > 0) continue;
      const d = dist(npc.x, npc.z, p.x, p.z);
      if (d < npc.aggro && d < best) { best = d; target = p; }
    }

    npc.targetId = target ? target.id : null;
    let desired = npc.rot;
    let throttle = 0.55;

    if (target) {
      npc.state = 'chase';
      const d = best;
      const toTarget = Math.atan2(target.x - npc.x, target.z - npc.z);
      if (d > npc.range * 0.82) {
        desired = toTarget;
        throttle = 1;
      } else if (d < npc.range * 0.45) {
        desired = toTarget + Math.PI;
        throttle = 0.7;
      } else {
        // circle the target so broadsides keep bearing
        desired = toTarget + Math.PI / 2 * (npc.id.charCodeAt(npc.id.length - 1) % 2 ? 1 : -1);
        throttle = 0.55;
      }
      npc.fireCd -= dt;
      if (npc.fireCd <= 0 && d < npc.range) {
        npc.fireCd = (npc.boss ? 1.9 : 2.8) + this.rng() * 1.2;
        const spread = (this.rng() - 0.5) * 0.16;
        const hitChance = npc.boss ? 0.82 : 0.62;
        const hit = this.rng() < hitChance;
        this.events.push({
          type: 'shot',
          npcId: npc.id,
          from: { x: npc.x, z: npc.z },
          to: { x: target.x + (this.rng() - 0.5) * 30, z: target.z + (this.rng() - 0.5) * 30 },
          rot: npc.rot,
          hostile: true
        });
        if (hit) {
          const dmg = Math.round(npc.damage * (0.85 + this.rng() * 0.4));
          target.hp = Math.max(0, target.hp - dmg);
          target.lastHit = this.elapsed;
          if (target.hp <= 0) target.alive = false;
          this.events.push({ type: 'playerHit', playerId: target.id, npcId: npc.id, dmg, hp: target.hp, x: target.x, z: target.z });
        }
      }
    } else {
      npc.state = 'patrol';
      const d = dist(npc.x, npc.z, npc.patrol.x, npc.patrol.z);
      if (d > 90) desired = Math.atan2(npc.patrol.x - npc.x, npc.patrol.z - npc.z);
      else desired = npc.rot + Math.sin(this.elapsed * 0.2 + npc.x) * 0.25;
      throttle = 0.35;
    }

    // avoid islands
    for (const isl of this.islands) {
      const d = dist(npc.x, npc.z, isl.x, isl.z);
      const keep = isl.radius + 46;
      if (d < keep) {
        const away = Math.atan2(npc.x - isl.x, npc.z - isl.z);
        desired = away;
        throttle = 1;
        break;
      }
    }

    // stay inside the world
    const dc = Math.hypot(npc.x, npc.z);
    if (dc > 1320) {
      desired = Math.atan2(-npc.x, -npc.z);
      throttle = 1;
    }

    const turn = npc.turn * dt;
    npc.rot += Math.max(-turn, Math.min(turn, angleDiff(npc.rot, desired)));
    const spd = npc.speed * throttle * (npc.state === 'chase' ? 1 : 0.7);
    npc.x += Math.sin(npc.rot) * spd * dt;
    npc.z += Math.cos(npc.rot) * spd * dt;
    const c = clampSea(npc.x, npc.z);
    npc.x = c.x; npc.z = c.z;
  }

  damageNpc(npcId, amount, playerId) {
    const npc = this.npcs.get(npcId);
    if (!npc || !npc.alive) return { ok: false, reason: 'gone' };
    npc.hp = Math.max(0, npc.hp - amount);
    const p = this.players.get(playerId);
    if (p) p.lastHit = this.elapsed;
    this.events.push({ type: 'npcHit', npcId, dmg: amount, hp: npc.hp, by: playerId, x: npc.x, z: npc.z });
    if (npc.hp <= 0) {
      npc.alive = false;
      npc.sunkAt = this.elapsed;
      const loot = rollLoot(npc, this.rng);
      const crate = {
        id: this.id('loot'),
        x: npc.x, z: npc.z,
        drops: loot.drops,
        gold: loot.gold,
        xp: loot.xp,
        ttl: 150,
        bob: 0
      };
      this.loot.set(crate.id, crate);
      this.events.push({ type: 'sink', npc: this.publicNpc(npc), x: npc.x, z: npc.z, by: playerId });
      this.events.push({ type: 'lootSpawn', loot: this.publicLoot(crate) });
    }
    return { ok: true, hp: npc.hp, sank: !npc.alive };
  }

  respawnNpc(npc) {
    const isl = this.islands[Math.floor(this.rng() * this.islands.length)];
    const a = this.rng() * TAU;
    const r = isl.radius + 120 + this.rng() * 160;
    npc.x = isl.x + Math.sin(a) * r;
    npc.z = isl.z + Math.cos(a) * r;
    npc.patrol = { x: npc.x, z: npc.z };
    npc.rot = this.rng() * TAU;
    npc.hp = npc.maxHp;
    npc.alive = true;
    npc.state = 'patrol';
    npc.fireCd = 2;
    this.events.push({ type: 'spawn', npc: this.publicNpc(npc) });
  }

  publicLoot(l) {
    return { id: l.id, x: l.x, z: l.z, drops: l.drops, gold: l.gold, xp: l.xp, ttl: l.ttl };
  }

  claimLoot(lootId, playerId) {
    const l = this.loot.get(lootId);
    if (!l) return null;
    this.loot.delete(lootId);
    const p = this.players.get(playerId);
    if (p) p.x = p.x;
    this.events.push({ type: 'lootClaimed', lootId, by: playerId, x: l.x, z: l.z });
    return { drops: l.drops, gold: l.gold, xp: l.xp };
  }

  snapshot() {
    const npcs = [];
    for (const n of this.npcs.values()) {
      if (!n.alive) continue;
      npcs.push([n.id, n.x, n.z, n.rot, n.hp, n.state]);
    }
    const loot = [];
    for (const l of this.loot.values()) loot.push([l.id, l.x, l.z]);
    return { npcs, loot };
  }
}

import http from 'node:http';
import fs from 'node:fs/promises';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { WebSocketServer } from 'ws';
import { SeaSim } from '../public/src/shared/sim.js';
import { levelFromXp, dist, cannonDamage, xpForLevel } from '../public/src/shared/rules.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const PUBLIC = path.join(ROOT, 'public');
const DATA = path.join(ROOT, 'data');
const PORT = Number(process.env.PORT || 3002);
const TICK = 1 / 12;

const islands = JSON.parse(await fs.readFile(path.join(PUBLIC, 'data/islands.json'), 'utf8'));
const shipData = JSON.parse(await fs.readFile(path.join(PUBLIC, 'data/ships.json'), 'utf8'));
const fruitData = JSON.parse(await fs.readFile(path.join(PUBLIC, 'data/fruits.json'), 'utf8'));

await fs.mkdir(DATA, { recursive: true });

/* ---------------------------------- static --------------------------------- */

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.webmanifest': 'application/manifest+json'
};

async function serveStatic(req, res) {
  const url = new URL(req.url, 'http://localhost');
  let pathname = decodeURIComponent(url.pathname);
  if (pathname === '/') pathname = '/index.html';
  const file = path.join(PUBLIC, pathname);
  if (!file.startsWith(PUBLIC)) { res.writeHead(403).end('forbidden'); return; }
  try {
    const buf = await fs.readFile(file);
    res.writeHead(200, {
      'content-type': MIME[path.extname(file)] || 'application/octet-stream',
      'cache-control': 'no-cache',
      'x-content-type-options': 'nosniff'
    });
    res.end(buf);
  } catch {
    res.writeHead(404, { 'content-type': 'text/plain' }).end('not found');
  }
}

/* --------------------------------- accounts -------------------------------- */

const accountsFile = path.join(DATA, 'accounts.json');
let accounts = {};
try { accounts = JSON.parse(await fs.readFile(accountsFile, 'utf8')); } catch { accounts = {}; }
let writeQueue = Promise.resolve();
function persistAccounts() {
  writeQueue = writeQueue.then(async () => {
    const tmp = accountsFile + '.tmp';
    await fs.writeFile(tmp, JSON.stringify(accounts, null, 2));
    await fs.rename(tmp, accountsFile);
  }).catch((e) => console.error('account write failed', e));
  return writeQueue;
}

const tokens = new Map();

function scrypt(password, salt) {
  return crypto.scryptSync(password, salt, 32).toString('hex');
}

function readBody(req, limit = 96 * 1024) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on('data', (c) => {
      size += c.length;
      if (size > limit) { reject(new Error('too large')); req.destroy(); return; }
      chunks.push(c);
    });
    req.on('end', () => {
      try { resolve(JSON.parse(Buffer.concat(chunks).toString('utf8') || '{}')); }
      catch { reject(new Error('bad json')); }
    });
    req.on('error', reject);
  });
}

function json(res, code, body) {
  res.writeHead(code, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' });
  res.end(JSON.stringify(body));
}

function publicAccount(name, acc) {
  return {
    name,
    createdAt: acc.createdAt,
    profile: acc.profile || null
  };
}

async function handleApi(req, res) {
  const url = new URL(req.url, 'http://localhost');
  try {
    if (req.method === 'POST' && url.pathname === '/api/register') {
      const { name, password } = await readBody(req);
      const clean = String(name || '').trim();
      if (!/^[A-Za-z0-9_ÄÖÜäöüß-]{3,16}$/.test(clean)) return json(res, 400, { error: 'Name: 3-16 Zeichen, Buchstaben/Zahlen/_/-' });
      if (typeof password !== 'string' || password.length < 4) return json(res, 400, { error: 'Passwort: mindestens 4 Zeichen' });
      const key = clean.toLowerCase();
      if (accounts[key]) return json(res, 409, { error: 'Name bereits vergeben' });
      const salt = crypto.randomBytes(16).toString('hex');
      accounts[key] = { name: clean, salt, hash: scrypt(password, salt), createdAt: Date.now(), profile: null };
      await persistAccounts();
      const token = crypto.randomBytes(24).toString('hex');
      tokens.set(token, key);
      return json(res, 200, { token, ...publicAccount(clean, accounts[key]) });
    }
    if (req.method === 'POST' && url.pathname === '/api/login') {
      const { name, password } = await readBody(req);
      const key = String(name || '').trim().toLowerCase();
      const acc = accounts[key];
      if (!acc || scrypt(String(password || ''), acc.salt) !== acc.hash) return json(res, 401, { error: 'Name oder Passwort falsch' });
      const token = crypto.randomBytes(24).toString('hex');
      tokens.set(token, key);
      return json(res, 200, { token, ...publicAccount(acc.name, acc) });
    }
    const auth = (req.headers.authorization || '').replace(/^Bearer\s+/i, '');
    const key = tokens.get(auth);
    if (url.pathname === '/api/save') {
      if (!key || !accounts[key]) return json(res, 401, { error: 'Nicht angemeldet' });
      if (req.method === 'GET') return json(res, 200, { profile: accounts[key].profile });
      if (req.method === 'PUT') {
        const { profile } = await readBody(req);
        if (!profile || typeof profile !== 'object') return json(res, 400, { error: 'Profil fehlt' });
        accounts[key].profile = { ...profile, savedAt: Date.now() };
        await persistAccounts();
        return json(res, 200, { ok: true, savedAt: accounts[key].profile.savedAt });
      }
    }
    return json(res, 404, { error: 'unbekannt' });
  } catch (err) {
    return json(res, 400, { error: err.message });
  }
}

