const server = http.createServer(async (req, res) => {
  if (req.url === '/health') return json(res, 200, { ok: true, players: wss.clients.size, uptime: process.uptime() });
  if (req.url.startsWith('/api/')) return handleApi(req, res);
  return serveStatic(req, res);
});

const sim = new SeaSim({ islands, enemies: shipData.enemies });

const wss = new WebSocketServer({ server, path: '/ws' });

const sockets = new Map();
let nextPlayer = 1;

function send(ws, msg) {
  if (ws.readyState === 1) ws.send(JSON.stringify(msg));
}

function broadcast(msg, except) {
  const raw = JSON.stringify(msg);
  for (const client of wss.clients) {
    if (client !== except && client.readyState === 1) client.send(raw);
  }
}

function playerPublic(p) {
  return {
    id: p.id, name: p.name, faction: p.faction, ship: p.ship, fruit: p.fruit,
    x: p.x, z: p.z, rot: p.rot, hp: p.hp, maxHp: p.maxHp,
    level: p.level, xp: p.xp, gold: p.gold, bounty: p.bounty, title: p.title
  };
}

function shipOf(id) {
  return shipData.playerShips.find((s) => s.id === id) || shipData.playerShips[0];
}

wss.on('connection', (ws, req) => {
  ws.isAlive = true;
  ws.msgCount = 0;
  ws.windowStart = Date.now();
  ws.on('pong', () => { ws.isAlive = true; });

  ws.on('message', (raw) => {
    if (raw.length > 8192) return;
    if (Date.now() - ws.windowStart > 1000) { ws.windowStart = Date.now(); ws.msgCount = 0; }
    if (++ws.msgCount > 60) return;

    let msg;
    try { msg = JSON.parse(raw.toString()); } catch { return; }
    if (!msg || typeof msg.t !== 'string') return;

    if (msg.t === 'join') {
      if (ws.player) return;
      const id = 'p' + (nextPlayer++);
      const name = String(msg.name || 'Kapitän').slice(0, 16).replace(/[<>]/g, '');
      const faction = ['pirate', 'marine', 'merchant', 'temple', 'blackmarket'].includes(msg.faction) ? msg.faction : 'pirate';
      const ship = shipOf(msg.ship).id;
      const fruit = fruitData.some((f) => f.id === msg.fruit) ? msg.fruit : null;
      const lvl = levelFromXp(Math.max(0, Number(msg.xp) || 0));
      const shipDef = shipOf(ship);
      const maxHp = shipDef.hp + 25 * Math.min(3, Number(msg.skills?.seemannsblut) || 0);
      const player = sim.addPlayer(id, {
        name, faction, x: Number(msg.x) || 0, z: Number(msg.z) || 60,
        rot: Number(msg.rot) || 0, hp: maxHp, maxHp
      });
      player.ship = ship;
      player.fruit = fruit;
      player.level = lvl.level;
      player.xp = Math.max(0, Number(msg.xp) || 0);
      player.gold = Math.max(0, Number(msg.gold) || 0);
      player.bounty = Math.max(0, Number(msg.bounty) || 0);
      player.skills = msg.skills && typeof msg.skills === 'object' ? msg.skills : {};
      player.title = String(msg.title || '').slice(0, 32);
      player.lastFire = 0;
      player.lastAbility = {};
      player.passive = fruitData.find((f) => f.id === fruit)?.passive || '';
      ws.player = player;
      sockets.set(id, ws);
      send(ws, {
        t: 'welcome',
        id,
        self: playerPublic(player),
        players: [...sim.players.values()].filter((p) => p.id !== id).map(playerPublic),
        snapshot: sim.snapshot(),
        online: wss.clients.size
      });
      broadcast({ t: 'joined', player: playerPublic(player) }, ws);
      broadcast({ t: 'online', count: wss.clients.size });
      return;
    }

    const p = ws.player;
    if (!p) return;

    if (msg.t === 'state') {
      sim.setPlayerPos(p.id, Number(msg.x) || 0, Number(msg.z) || 0, Number(msg.rot) || 0, Number(msg.hp));
      p.level = levelFromXp(Math.max(0, Number(msg.xp) || p.xp)).level;
      if (typeof msg.xp === 'number') p.xp = Math.max(0, msg.xp);
      if (typeof msg.gold === 'number') p.gold = Math.max(0, msg.gold);
      if (typeof msg.bounty === 'number') p.bounty = Math.max(0, msg.bounty);
    } else if (msg.t === 'fire') {
      const now = Date.now();
      const cooldown = 520 - 40 * Math.min(3, Number(p.skills?.breitseite) || 0);
      if (now - p.lastFire < cooldown) return;
      p.lastFire = now;
      const npc = sim.npcs.get(String(msg.npcId));
      if (!npc || !npc.alive) return;
      if (dist(p.x, p.z, npc.x, npc.z) > 340) return;
      const def = shipOf(p.ship);
      const dmg = cannonDamage(def.damage * 2.2, p.skills, p.fruit === 'magma' ? 0.1 : 0);
      const res = sim.damageNpc(npc.id, dmg, p.id);
      if (res.ok) broadcast({ t: 'event', ...sim.events.find((e) => e.type === 'npcHit') });
    } else if (msg.t === 'ability') {
      const fruit = fruitData.find((f) => f.id === p.fruit);
      if (!fruit) return;
      const ability = fruit.abilities.find((a) => a.id === msg.abilityId);
      if (!ability) return;
      const now = Date.now();
      const last = p.lastAbility[ability.id] || 0;
      if (now - last < ability.cooldown * 1000) return;
      p.lastAbility[ability.id] = now;
      let hits = 0;
      if (ability.damage > 0) {
        for (const npc of sim.npcs.values()) {
          if (!npc.alive) continue;
          if (dist(p.x, p.z, npc.x, npc.z) <= ability.range) {
            sim.damageNpc(npc.id, ability.damage, p.id);
            hits++;
            if (hits >= 6) break;
          }
        }
      }
      if (ability.id === 'nebelhort') p.hp = Math.min(p.maxHp, p.hp + 35);
      broadcast({
        t: 'event', type: 'ability', ability: ability.id, fruit: fruit.id,
        x: p.x, z: p.z, by: p.id, hits, color: fruit.color
      });
    } else if (msg.t === 'claim') {
      const l = sim.loot.get(String(msg.lootId));
      if (!l) return;
      if (dist(p.x, p.z, l.x, l.z) > 60) return;
      const reward = sim.claimLoot(l.id, p.id);
      if (!reward) return;
      p.xp += reward.xp;
      p.gold += reward.gold;
      const lvl = levelFromXp(p.xp);
      if (lvl.level > p.level) {
        p.level = lvl.level;
        send(ws, { t: 'levelup', level: p.level, need: xpForLevel(p.level) });
      }
      send(ws, { t: 'reward', ...reward, xpTotal: p.xp, goldTotal: p.gold, level: p.level, need: lvl.need, rest: lvl.rest });
      broadcast({ t: 'event', type: 'lootClaimed', x: l.x, z: l.z, by: p.id });
    } else if (msg.t === 'chat') {
      const text = String(msg.text || '').replace(/[\u0000-\u001f<>]/g, '').trim().slice(0, 160);
      if (!text) return;
      broadcast({ t: 'chat', from: p.name, faction: p.faction, text, at: Date.now() });
    } else if (msg.t === 'ping') {
      send(ws, { t: 'pong', at: Date.now() });
    }
  });

  ws.on('close', () => {
    const p = ws.player;
    if (p) {
      sim.removePlayer(p.id);
      sockets.delete(p.id);
      broadcast({ t: 'left', id: p.id });
      broadcast({ t: 'online', count: wss.clients.size });
    }
  });
});

setInterval(() => {
  const events = sim.tick(TICK);
  for (const ev of events) {
    if (ev.type === 'playerHit') {
      const target = sockets.get(ev.playerId);
      if (target) send(target, { t: 'hit', dmg: ev.dmg, hp: ev.hp, x: ev.x, z: ev.z });
    }
  }
  const snap = sim.snapshot();
  broadcast({
    t: 'snapshot',
    players: [...sim.players.values()].map(playerPublic),
    npcs: snap.npcs,
    loot: snap.loot,
    online: wss.clients.size
  });
  // fire/sink events are visual for everyone
  for (const ev of events) {
    if (ev.type === 'shot' || ev.type === 'sink' || ev.type === 'spawn') {
      broadcast({ t: 'event', ...ev });
    }
  }
}, 1000 / 12);

setInterval(() => {
  for (const ws of wss.clients) {
    if (!ws.isAlive) { ws.terminate(); continue; }
    ws.isAlive = false;
    ws.ping();
  }
}, 30000);

server.listen(PORT, () => {
  console.log(`⚓ Kaperfahrt läuft auf http://localhost:${PORT}`);
  console.log(`   WebSocket: ws://localhost:${PORT}/ws`);
});

for (const sig of ['SIGINT', 'SIGTERM']) {
  process.on(sig, () => {
    console.log('\\nAnker lichten. Tschüss.');
    server.close(() => process.exit(0));
    setTimeout(() => process.exit(0), 1500);
  });
}

import * as THREE from 'three';

export const SEA = 1500;

export function waveHeight(x, z, t) {
  return Math.sin(x * 0.055 + t * 0.9) * 0.62 +
    Math.sin(z * 0.073 + t * 1.25) * 0.5 +
    Math.sin((x + z) * 0.031 + t * 0.6) * 0.8;
}

const FACTION_COLORS = {
  pirate: 0x1c1c22,
  marine: 0xe8eef4,
  merchant: 0xc9a227,
  temple: 0x8a5cd6,
  blackmarket: 0x3d2b4f,
  neutral: 0x2f8f83
};

export function factionColor(f) {
  return FACTION_COLORS[f] || FACTION_COLORS.neutral;
}

export const BIOME = {
  temperate: { sand: 0xd9c79a, grass: 0x4e7f4a, rock: 0x6f6a5f, tree: 0x2f5c37 },
  tropical: { sand: 0xefdcae, grass: 0x3f8f52, rock: 0x7a7361, tree: 0x2a7a3d },
  storm: { sand: 0x9a917e, grass: 0x3d5a45, rock: 0x4d4a48, tree: 0x28402f },
  mystic: { sand: 0xe6d3b0, grass: 0x5b6f9a, rock: 0x6b5d86, tree: 0x8a5cd6 },
  swamp: { sand: 0x8f8a6a, grass: 0x4a5f3a, rock: 0x5a5445, tree: 0x3d4a2c },
  rocky: { sand: 0xbdb49b, grass: 0x5c6b4f, rock: 0x7d7669, tree: 0x33502f },
  fog: { sand: 0xa9a99c, grass: 0x4a5a4f, rock: 0x5c5c5c, tree: 0x2f3a33 },
  arctic: { sand: 0xdfe6e8, grass: 0x7d948c, rock: 0x8f9aa0, tree: 0x3e5a52 },
  volcanic: { sand: 0x3a3230, grass: 0x4a3a35, rock: 0x2b2523, tree: 0x3d2f2a }
};

const OCEAN_VERT = /* glsl */`
  uniform float uTime;
  varying vec3 vWorld;
  varying vec3 vNormal;

  float wave(vec2 p, float t) {
    return sin(p.x * 0.055 + t * 0.9) * 0.62
         + sin(p.y * 0.073 + t * 1.25) * 0.5
         + sin((p.x + p.y) * 0.031 + t * 0.6) * 0.8;
  }

  void main() {
    vec3 p = position;
    float h = wave(p.xz, uTime);
    p.y = h;
    float e = 1.4;
    float hx = wave(p.xz + vec2(e, 0.0), uTime);
    float hz = wave(p.xz + vec2(0.0, e), uTime);
    vNormal = normalize(vec3(h - hx, e, h - hz));
    vec4 world = modelMatrix * vec4(p, 1.0);
    vWorld = world.xyz;
    gl_Position = projectionMatrix * viewMatrix * world;
  }
`;

const OCEAN_FRAG = /* glsl */`
  uniform float uTime;
  uniform vec3 uSunDir;
  uniform vec3 uDeep;
  uniform vec3 uShallow;
  uniform vec3 uFogColor;
  uniform float uFogDensity;
  uniform vec3 uCamPos;
  uniform vec3 uIslands[12];
  varying vec3 vWorld;
  varying vec3 vNormal;

  void main() {
    vec3 n = normalize(vNormal);
    vec3 viewDir = normalize(uCamPos - vWorld);
    float fres = pow(1.0 - max(dot(n, viewDir), 0.0), 2.6);

    float d = 1e9;
    for (int i = 0; i < 12; i++) {
      d = min(d, distance(vWorld.xz, uIslands[i].xy) - uIslands[i].z);
    }
    float shallow = smoothstep(70.0, 0.0, d);
    vec3 base = mix(uDeep, uShallow, shallow * 0.75 + fres * 0.35);

    vec3 halfDir = normalize(uSunDir + viewDir);
    float spec = pow(max(dot(n, halfDir), 0.0), 90.0) * 1.5;
    float sparkle = pow(max(dot(n, halfDir), 0.0), 420.0) * 2.5;

    float foam = smoothstep(7.0, -1.0, d) * (0.5 + 0.5 * sin(uTime * 1.8 + vWorld.x * 0.25 + vWorld.z * 0.2));
    base = mix(base, vec3(0.88, 0.96, 0.97), clamp(foam, 0.0, 0.85));

    vec3 col = base + vec3(1.0, 0.94, 0.78) * (spec + sparkle);
    float fog = 1.0 - exp(-uFogDensity * uFogDensity * distance(uCamPos, vWorld) * distance(uCamPos, vWorld));
    col = mix(col, uFogColor, clamp(fog, 0.0, 1.0));
    gl_FragColor = vec4(col, 1.0);
  }
`;

const SKY_VERT = /* glsl */`
  varying vec3 vDir;
  void main() {
    vDir = normalize(position);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const SKY_FRAG = /* glsl */`
  uniform vec3 uTop;
  uniform vec3 uHorizon;
  uniform vec3 uSunDir;
  uniform float uNight;
  varying vec3 vDir;

  float hash(vec3 p) {
    p = fract(p * 0.3183099 + vec3(0.1, 0.2, 0.3));
    p *= 17.0;
    return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
  }

  void main() {
    float h = clamp(vDir.y * 1.6 + 0.15, 0.0, 1.0);
    vec3 col = mix(uHorizon, uTop, pow(h, 0.75));
    float sun = max(dot(normalize(vDir), normalize(uSunDir)), 0.0);
    col += vec3(1.0, 0.82, 0.55) * pow(sun, 220.0) * 2.2;
    col += vec3(1.0, 0.7, 0.4) * pow(sun, 12.0) * 0.28;
    if (uNight > 0.01) {
      vec3 sp = floor(vDir * 380.0);
      float star = step(0.9975, hash(sp)) * uNight;
      col += vec3(0.9, 0.95, 1.0) * star * 1.2;
    }
    gl_FragColor = vec4(col, 1.0);
  }
`;

export class World {
  constructor(scene, islands) {
    this.scene = scene;
    this.islands = islands;
    this.time = 0;
    this.sunDir = new THREE.Vector3(0.5, 0.75, 0.35).normalize();
    this.night = 0;
    this.clouds = [];
    this.labels = [];
    this.sunLight = new THREE.DirectionalLight(0xfff0d8, 2.2);
    this.hemi = new THREE.HemisphereLight(0xbfe9ff, 0x2c4a52, 1.15);
    this.scene.add(this.sunLight, this.hemi);
    this.scene.add(new THREE.AmbientLight(0x9fd6dd, 0.25));
    this.buildSky();
    this.buildOcean();
    this.buildIslands();
    this.buildClouds();
    this.buildHorizon();
  }

  buildSky() {
    this.skyUniforms = {
      uTop: { value: new THREE.Color(0x2e7fb8) },
      uHorizon: { value: new THREE.Color(0xbfe7ea) },
      uSunDir: { value: this.sunDir },
      uNight: { value: 0 }
    };
    const geo = new THREE.SphereGeometry(3800, 32, 20);
    const mat = new THREE.ShaderMaterial({
      uniforms: this.skyUniforms,
      vertexShader: SKY_VERT,
      fragmentShader: SKY_FRAG,
      side: THREE.BackSide,
      depthWrite: false,
      fog: false
    });
    this.sky = new THREE.Mesh(geo, mat);
    this.sky.frustumCulled = false;
    this.scene.add(this.sky);
  }

  buildOcean() {
    const geo = new THREE.PlaneGeometry(3600, 3600, 300, 300);
    geo.rotateX(-Math.PI / 2);
    this.oceanUniforms = {
      uTime: { value: 0 },
      uSunDir: { value: this.sunDir },
      uDeep: { value: new THREE.Color(0x0b3550) },
      uShallow: { value: new THREE.Color(0x1c8f8f) },
      uFogColor: { value: new THREE.Color(0xbfe7ea) },
      uFogDensity: { value: 0.00072 },
      uCamPos: { value: new THREE.Vector3() },
      uIslands: { value: Array.from({ length: 12 }, (_, i) => {
        const isl = this.islands[i];
        return isl ? new THREE.Vector3(isl.x, isl.z, isl.radius * 0.9) : new THREE.Vector3(9999, 9999, 0);
      }) }
    };
    const mat = new THREE.ShaderMaterial({
      uniforms: this.oceanUniforms,
      vertexShader: OCEAN_VERT,
      fragmentShader: OCEAN_FRAG,
      fog: false
    });
    this.ocean = new THREE.Mesh(geo, mat);
    this.ocean.frustumCulled = false;
    this.scene.add(this.ocean);
  }

  buildHorizon() {
    // A soft ring of distant silhouettes keeps the sea from looking endless-flat.
    const group = new THREE.Group();
    const mat = new THREE.MeshBasicMaterial({ color: 0x7fb0b8, transparent: true, opacity: 0.55, fog: true });
    for (let i = 0; i < 26; i++) {
      const a = (i / 26) * Math.PI * 2 + Math.sin(i * 3.1) * 0.05;
      const r = 2350 + Math.sin(i * 7.7) * 120;
      const h = 30 + Math.abs(Math.sin(i * 2.3)) * 90;
      const m = new THREE.Mesh(new THREE.ConeGeometry(90 + Math.sin(i) * 30, h, 5), mat);
      m.position.set(Math.sin(a) * r, h / 2 - 20, Math.cos(a) * r);
      m.rotation.y = a;
      group.add(m);
    }
    this.scene.add(group);
  }

  buildClouds() {
    const mat = new THREE.MeshLambertMaterial({ color: 0xffffff, transparent: true, opacity: 0.85, fog: true });
    for (let i = 0; i < 22; i++) {
      const g = new THREE.Group();
      const n = 3 + (i % 3);
      for (let j = 0; j < n; j++) {
        const s = 16 + Math.random() * 22;
        const m = new THREE.Mesh(new THREE.SphereGeometry(s, 8, 6), mat);
        m.scale.y = 0.45;
        m.position.set((j - n / 2) * s * 0.9, Math.random() * 5, Math.random() * 18);
        g.add(m);
      }
      const a = Math.random() * Math.PI * 2;
      const r = 300 + Math.random() * 1600;
      g.position.set(Math.sin(a) * r, 120 + Math.random() * 90, Math.cos(a) * r);
      g.userData.speed = 1.5 + Math.random() * 2;
      this.clouds.push(g);
      this.scene.add(g);
    }
  }

  buildIslands() {
    for (const isl of this.islands) {
      const palette = BIOME[isl.biome] || BIOME.temperate;
      const group = new THREE.Group();
      group.position.set(isl.x, 0, isl.z);
      const r = isl.radius;

      // shallow shelf
      const shelf = new THREE.Mesh(
        new THREE.CylinderGeometry(r * 1.22, r * 1.3, 2.4, 40),
        new THREE.MeshLambertMaterial({ color: 0x2aa3a0, transparent: true, opacity: 0.55 })
      );
      shelf.position.y = -1.6;
      group.add(shelf);

      // beach
      const beach = new THREE.Mesh(
        new THREE.CylinderGeometry(r, r * 1.06, 5, 40),
        new THREE.MeshLambertMaterial({ color: palette.sand })
      );
      beach.position.y = -0.4;
      group.add(beach);

      // land mass
      const landGeo = new THREE.SphereGeometry(r * 0.86, 28, 14, 0, Math.PI * 2, 0, Math.PI / 2);
      const land = new THREE.Mesh(landGeo, new THREE.MeshLambertMaterial({ color: palette.grass }));
      land.scale.y = 0.16 + (isl.type === 'volcano' ? 0.24 : 0.12);
      land.position.y = 2.0;
      group.add(land);

      // rocks / peak
      if (isl.type === 'volcano') {
        const cone = new THREE.Mesh(
          new THREE.ConeGeometry(r * 0.34, r * 0.75, 9),
          new THREE.MeshLambertMaterial({ color: palette.rock })
        );
        cone.position.y = r * 0.3;
        group.add(cone);
        const lava = new THREE.Mesh(
          new THREE.ConeGeometry(r * 0.13, r * 0.2, 9),
          new THREE.MeshBasicMaterial({ color: 0xff5a1f })
        );
        lava.position.y = r * 0.62;
        group.add(lava);
        const glow = new THREE.PointLight(0xff6a2a, 2.5, 260, 2);
        glow.position.y = r * 0.6;
        group.add(glow);
      } else if (isl.type === 'fortress') {
        this.addFortress(group, r, isl, palette);
      } else if (isl.type === 'temple') {
        this.addTemple(group, r, palette);
      } else if (isl.type === 'town' || isl.type === 'market' || isl.type === 'pirate' || isl.type === 'smuggler') {
        this.addTown(group, r, isl, palette);
      } else {
        this.addRuins(group, r, palette);
      }

      // palms
      const palmCount = Math.round(4 + r / 18);
      for (let i = 0; i < palmCount; i++) {
        const a = (i / palmCount) * Math.PI * 2 + Math.sin(i * 5.3) * 0.4;
        const rr = r * (0.42 + (i % 5) * 0.09);
        const palm = makePalm(palette.tree, 0.8 + (i % 4) * 0.12);
        palm.position.set(Math.sin(a) * rr, 3 + (1 - rr / r) * r * 0.12, Math.cos(a) * rr);
        palm.rotation.z = Math.sin(i * 2.1) * 0.08;
        group.add(palm);
      }

      // dock pointing toward the world centre
      const dockAngle = Math.atan2(-isl.x, -isl.z);
      const dock = this.makeDock(r, isl, palette);
      dock.position.set(Math.sin(dockAngle) * (r + 8), 1.2, Math.cos(dockAngle) * (r + 8));
      dock.rotation.y = dockAngle;
      group.add(dock);
      isl.dock = {
        x: isl.x + Math.sin(dockAngle) * (r + 30),
        z: isl.z + Math.cos(dockAngle) * (r + 30),
        angle: dockAngle
      };

      // flag
      const flagPole = new THREE.Mesh(
        new THREE.CylinderGeometry(0.35, 0.45, 30, 6),
        new THREE.MeshLambertMaterial({ color: 0x3a2a1c })
      );
      flagPole.position.set(0, 16, 0);
      group.add(flagPole);
      const flagMat = new THREE.MeshLambertMaterial({ color: factionColor(isl.faction), side: THREE.DoubleSide });
      const flag = new THREE.Mesh(new THREE.PlaneGeometry(9, 5, 6, 1), flagMat);
      flag.position.set(4.6, 27, 0);
      group.add(flag);

      // name label
      const label = makeLabel(isl.name, isl.faction);
      label.position.set(0, 52, 0);
      group.add(label);
      this.labels.push(label);

      this.scene.add(group);
      isl.group = group;
      isl.waveFlag = flag;
    }
  }

  addTown(group, r, isl, palette) {
    const wallMat = new THREE.MeshLambertMaterial({ color: 0xe4d6b8 });
    const roofMat = new THREE.MeshLambertMaterial({ color: isl.faction === 'pirate' ? 0x5a2f2a : 0x8c4a35 });
    const woodMat = new THREE.MeshLambertMaterial({ color: 0x6b4a2f });
    const count = isl.type === 'town' ? 9 : 6;
    for (let i = 0; i < count; i++) {
      const a = (i / count) * Math.PI * 2 + 0.4;
      const rr = r * (0.24 + (i % 3) * 0.14);
      const w = 8 + (i % 3) * 3;
      const h = 7 + (i % 4) * 2.5;
      const house = new THREE.Group();
      const body = new THREE.Mesh(new THREE.BoxGeometry(w, h, w * 0.8), wallMat);
      body.position.y = h / 2;
      house.add(body);
      const roof = new THREE.Mesh(new THREE.ConeGeometry(w * 0.82, 4.5, 4), roofMat);
      roof.position.y = h + 2.2;
      roof.rotation.y = Math.PI / 4;
      house.add(roof);
      const door = new THREE.Mesh(new THREE.BoxGeometry(1.8, 3, 0.4), woodMat);
      door.position.set(0, 1.5, w * 0.4 + 0.1);
      house.add(door);
      house.position.set(Math.sin(a) * rr, 3.2, Math.cos(a) * rr);
      house.rotation.y = a + Math.PI;
      group.add(house);
    }
    if (isl.type === 'town') {
      // tavern with a big lantern
      const tavern = new THREE.Group();
      const body = new THREE.Mesh(new THREE.BoxGeometry(18, 11, 12), wallMat);
      body.position.y = 5.5;
      tavern.add(body);
      const roof = new THREE.Mesh(new THREE.ConeGeometry(14, 6, 4), roofMat);
      roof.position.y = 14;
      roof.rotation.y = Math.PI / 4;
      tavern.add(roof);
      const lantern = new THREE.Mesh(new THREE.SphereGeometry(1.1, 8, 6), new THREE.MeshBasicMaterial({ color: 0xffc86b }));
      lantern.position.set(0, 8, 6.4);
      tavern.add(lantern);
      tavern.position.set(0, 3.4, -r * 0.3);
      group.add(tavern);
    }
  }

  addFortress(group, r, isl, palette) {
    const stone = new THREE.MeshLambertMaterial({ color: 0xcfd6d6 });
    const wall = new THREE.Mesh(new THREE.CylinderGeometry(r * 0.5, r * 0.55, 16, 6), stone);
    wall.position.y = 10;
    group.add(wall);
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * Math.PI * 2;
      const tower = new THREE.Mesh(new THREE.CylinderGeometry(6, 7, 24, 8), stone);
      tower.position.set(Math.sin(a) * r * 0.5, 14, Math.cos(a) * r * 0.5);
      group.add(tower);
      const top = new THREE.Mesh(new THREE.ConeGeometry(7.4, 7, 8), new THREE.MeshLambertMaterial({ color: 0x2b4f6e }));
      top.position.set(Math.sin(a) * r * 0.5, 29, Math.cos(a) * r * 0.5);
      group.add(top);
    }
    const keep = new THREE.Mesh(new THREE.BoxGeometry(26, 34, 26), stone);
    keep.position.y = 20;
    group.add(keep);
  }

  addTemple(group, r, palette) {
    const stone = new THREE.MeshLambertMaterial({ color: 0xcfc3dd });
    const base = new THREE.Mesh(new THREE.CylinderGeometry(r * 0.36, r * 0.42, 5, 8), stone);
    base.position.y = 4;
    group.add(base);
    const hall = new THREE.Mesh(new THREE.BoxGeometry(24, 13, 18), stone);
    hall.position.y = 12;
    group.add(hall);
    const roof = new THREE.Mesh(new THREE.ConeGeometry(24, 9, 4), new THREE.MeshLambertMaterial({ color: 0x6d4fa0 }));
    roof.position.y = 22;
    roof.rotation.y = Math.PI / 4;
    group.add(roof);
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * Math.PI * 2 + Math.PI / 4;
      const pillar = new THREE.Mesh(new THREE.CylinderGeometry(1.2, 1.4, 20, 8), stone);
      pillar.position.set(Math.sin(a) * 22, 12, Math.cos(a) * 22);
      group.add(pillar);
    }
    const orb = new THREE.Mesh(new THREE.SphereGeometry(3, 12, 10), new THREE.MeshBasicMaterial({ color: 0xc9a8ff }));
    orb.position.y = 32;
    group.add(orb);
    const glow = new THREE.PointLight(0xb48cff, 2.2, 180, 2);
    glow.position.y = 32;
    group.add(glow);
  }

  addRuins(group, r, palette) {
    const stone = new THREE.MeshLambertMaterial({ color: 0x9a9584 });
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * Math.PI * 2;
      const h = 4 + (i % 3) * 5;
      const pillar = new THREE.Mesh(new THREE.CylinderGeometry(1.6, 2, h, 7), stone);
      pillar.position.set(Math.sin(a) * r * 0.3, h / 2 + 3, Math.cos(a) * r * 0.3);
      pillar.rotation.z = (i % 2 ? 0.15 : -0.1);
      group.add(pillar);
    }
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * Math.PI * 2;
      const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(4 + i, 0), stone);
      rock.position.set(Math.sin(a) * r * 0.6, 5, Math.cos(a) * r * 0.6);
      group.add(rock);
    }
  }

  makeDock(r, isl, palette) {
    const dock = new THREE.Group();
    const wood = new THREE.MeshLambertMaterial({ color: 0x6b4a2f });
    const deck = new THREE.Mesh(new THREE.BoxGeometry(7, 1, 40), wood);
    deck.position.y = 0;
    dock.add(deck);
    for (let i = 0; i < 6; i++) {
      const post = new THREE.Mesh(new THREE.CylinderGeometry(0.6, 0.6, 12, 5), wood);
      post.position.set(-3, -5, -16 + i * 6.5);
      dock.add(post);
      const post2 = post.clone();
      post2.position.x = 3;
      dock.add(post2);
    }
    const crane = new THREE.Mesh(new THREE.BoxGeometry(1, 14, 1), wood);
    crane.position.set(0, 7, 14);
    dock.add(crane);
    return dock;
  }

  update(dt, camera, elapsed) {
    this.time += dt;
    this.oceanUniforms.uTime.value = this.time;
    this.oceanUniforms.uCamPos.value.copy(camera.position);

    const cycle = (Math.sin(this.time * 0.012) + 1) / 2; // slow day/night
    const day = 0.25 + cycle * 0.75;
    this.sunDir.set(Math.cos(this.time * 0.012) * 0.8, 0.25 + day * 0.7, 0.35).normalize();
    this.sunLight.position.copy(this.sunDir).multiplyScalar(600);
    this.sunLight.intensity = 0.5 + day * 2.0;
    this.hemi.intensity = 0.35 + day * 0.9;
    this.night = 1 - day;

    const top = new THREE.Color(0x0a1830).lerp(new THREE.Color(0x2e7fb8), day);
    const horizon = new THREE.Color(0x1c2740).lerp(new THREE.Color(0xbfe7ea), day);
    this.skyUniforms.uTop.value.copy(top);
    this.skyUniforms.uHorizon.value.copy(horizon);
    this.skyUniforms.uNight.value = this.night;
    this.oceanUniforms.uFogColor.value.copy(horizon);
    this.oceanUniforms.uDeep.value.setRGB(0.02 + day * 0.03, 0.1 + day * 0.11, 0.18 + day * 0.15);
    this.oceanUniforms.uShallow.value.setRGB(0.03 + day * 0.08, 0.32 + day * 0.24, 0.32 + day * 0.24);
    this.sky.position.copy(camera.position);

    for (const c of this.clouds) {
      c.position.x += c.userData.speed * dt;
      if (c.position.x > 2200) c.position.x = -2200;
    }
    for (const isl of this.islands) {
      if (isl.waveFlag) isl.waveFlag.rotation.y = Math.sin(this.time * 2 + isl.x) * 0.18;
    }
  }
}

export function makePalm(color, scale = 1) {
  const group = new THREE.Group();
  const trunkMat = new THREE.MeshLambertMaterial({ color: 0x7a5a38 });
  const leafMat = new THREE.MeshLambertMaterial({ color, side: THREE.DoubleSide });
  const segments = 4;
  for (let i = 0; i < segments; i++) {
    const seg = new THREE.Mesh(new THREE.CylinderGeometry(0.55 - i * 0.06, 0.7 - i * 0.06, 4.2, 5), trunkMat);
    seg.position.y = 2 + i * 3.7;
    seg.position.x = Math.sin(i * 0.5) * 0.9;
    seg.rotation.z = Math.sin(i * 0.5) * 0.08;
    group.add(seg);
  }
  for (let i = 0; i < 6; i++) {
    const leaf = new THREE.Mesh(new THREE.ConeGeometry(2.4, 8, 4), leafMat);
    leaf.position.y = 16;
    leaf.rotation.z = Math.PI / 2.4;
    leaf.rotation.y = (i / 6) * Math.PI * 2;
    leaf.position.x = Math.sin((i / 6) * Math.PI * 2) * 3.2;
    leaf.position.z = Math.cos((i / 6) * Math.PI * 2) * 3.2;
    leaf.scale.y = 0.7;
    group.add(leaf);
  }
  group.scale.setScalar(scale);
  return group;
}

export function makeLabel(text, faction) {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, 512, 128);
  ctx.font = '600 54px Georgia, serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'rgba(4, 16, 22, 0.55)';
  const w = ctx.measureText(text).width + 48;
  ctx.beginPath();
  ctx.roundRect(256 - w / 2, 26, w, 76, 18);
  ctx.fill();
  ctx.strokeStyle = '#' + factionColor(faction).toString(16).padStart(6, '0');
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.fillStyle = '#f4ecd9';
  ctx.fillText(text, 256, 66);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, fog: false });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set(120, 30, 1);
  return sprite;
}

import * as THREE from 'three';

const sailCache = new Map();

function sailTexture(faction) {
  if (sailCache.has(faction)) return sailCache.get(faction);
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 384;
  const ctx = canvas.getContext('2d');
  const grad = ctx.createLinearGradient(0, 0, 0, 384);
  grad.addColorStop(0, '#f6eeda');
  grad.addColorStop(1, '#d9c9a8');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 512, 384);
  ctx.strokeStyle = 'rgba(120, 96, 66, 0.22)';
  ctx.lineWidth = 6;
  for (let i = 1; i < 6; i++) {
    ctx.beginPath();
    ctx.moveTo(0, i * 64);
    ctx.lineTo(512, i * 64);
    ctx.stroke();
  }
  const colors = {
    pirate: '#1d1d24', marine: '#22496e', merchant: '#a2761f',
    temple: '#6b4a9e', blackmarket: '#3d2b4f', neutral: '#2f8f83'
  };
  ctx.fillStyle = colors[faction] || colors.neutral;
  ctx.beginPath();
  ctx.arc(256, 160, 74, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#f2e7cf';
  ctx.font = 'bold 74px Georgia, serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(faction === 'marine' ? '⚓' : faction === 'temple' ? '☯' : '☠', 256, 166);
  ctx.strokeStyle = colors[faction] || colors.neutral;
  ctx.lineWidth = 10;
  ctx.strokeRect(8, 8, 496, 368);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  sailCache.set(faction, tex);
  return tex;
}

function makeSail(width, height, faction) {
  const geo = new THREE.PlaneGeometry(width, height, 10, 6);
  const pos = geo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i);
    const y = pos.getY(i);
    const bulge = Math.cos((x / width) * Math.PI) * (0.9 + 0.2 * Math.cos((y / height) * Math.PI));
    pos.setZ(i, bulge);
  }
  geo.computeVertexNormals();
  const mat = new THREE.MeshLambertMaterial({
    map: sailTexture(faction),
    side: THREE.DoubleSide,
    color: 0xffffff
  });
  return new THREE.Mesh(geo, mat);
}

export function buildShip({ shipId = 'sloop', faction = 'pirate', accent = 0x2f8f83 } = {}) {
  const group = new THREE.Group();
  const hullMat = new THREE.MeshLambertMaterial({ color: 0x4a3120 });
  const deckMat = new THREE.MeshLambertMaterial({ color: 0x9a7248 });
  const trimMat = new THREE.MeshLambertMaterial({ color: accent });
  const darkMat = new THREE.MeshLambertMaterial({ color: 0x1b1b20 });
  const goldMat = new THREE.MeshLambertMaterial({ color: 0xd8b25e, emissive: 0x4a3000, emissiveIntensity: 0.4 });

  // hull outline (top view), extruded and laid flat
  const shape = new THREE.Shape();
  shape.moveTo(0, 10);
  shape.quadraticCurveTo(3.5, 6.2, 3.3, -3.5);
  shape.lineTo(2.4, -7.5);
  shape.lineTo(-2.4, -7.5);
  shape.lineTo(-3.3, -3.5);
  shape.quadraticCurveTo(-3.5, 6.2, 0, 10);
  const hullGeo = new THREE.ExtrudeGeometry(shape, {
    depth: 3.2, bevelEnabled: true, bevelSize: 0.3, bevelThickness: 0.3,
    bevelSegments: 2, curveSegments: 10
  });
  hullGeo.rotateX(Math.PI / 2);
  const hull = new THREE.Mesh(hullGeo, hullMat);
  hull.position.y = 3.4;
  group.add(hull);

  const deck = new THREE.Mesh(new THREE.BoxGeometry(5.4, 0.5, 14.2), deckMat);
  deck.position.set(0, 3.6, -0.6);
  group.add(deck);

  const stripe = new THREE.Mesh(new THREE.BoxGeometry(6.5, 0.7, 12.6), trimMat);
  stripe.position.y = 1.5;
  group.add(stripe);

  // stern cabin
  const cabin = new THREE.Mesh(new THREE.BoxGeometry(4.4, 2.6, 4.4), deckMat);
  cabin.position.set(0, 4.9, -4.6);
  group.add(cabin);
  const cabinRoof = new THREE.Mesh(new THREE.BoxGeometry(5, 0.4, 5), trimMat);
  cabinRoof.position.set(0, 6.3, -4.6);
  group.add(cabinRoof);
  const window1 = new THREE.Mesh(new THREE.PlaneGeometry(1.4, 0.9), new THREE.MeshBasicMaterial({ color: 0xffd98a }));
  window1.position.set(0, 5.3, -2.38);
  group.add(window1);

  // bowsprit
  const bowsprit = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.28, 8, 6), hullMat);
  bowsprit.rotation.x = Math.PI / 2.55;
  bowsprit.position.set(0, 4.3, 9.6);
  group.add(bowsprit);

  const mastCount = shipId === 'galleon' ? 3 : shipId === 'brig' ? 2 : 2;
  const mastZ = mastCount === 3 ? [3.6, -0.2, -3.6] : mastCount === 2 ? [3.2, -2.2] : [1.8];
  const sails = [];
  const masts = [];
  mastZ.forEach((z, idx) => {
    const h = idx === 0 ? 17 : idx === 1 ? 15.5 : 13;
    const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.32, h, 6), hullMat);
    mast.position.set(0, 3.6 + h / 2, z);
    group.add(mast);
    masts.push(mast);

    const sailW = idx === 0 ? 8.6 : 7.4;
    const sailH = idx === 0 ? 6.4 : 5.2;
    const sail = makeSail(sailW, sailH, faction);
    sail.position.set(0, 3.6 + h * 0.62, z + 0.25);
    group.add(sail);
    sails.push(sail);

    const yard = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, sailW + 1.2, 5), darkMat);
    yard.rotation.z = Math.PI / 2;
    yard.position.set(0, 3.6 + h * 0.62 + sailH / 2, z + 0.2);
    group.add(yard);
  });

  // crow's nest
  const nest = new THREE.Mesh(new THREE.CylinderGeometry(1.2, 0.9, 0.8, 8), darkMat);
  nest.position.set(0, 19.6, mastZ[0]);
  group.add(nest);

  // flag
  const flag = new THREE.Mesh(
    new THREE.PlaneGeometry(3.4, 2, 6, 1),
    new THREE.MeshLambertMaterial({ map: sailTexture(faction), side: THREE.DoubleSide })
  );
  flag.position.set(1.8, 19.9, mastZ[0]);
  group.add(flag);

  // cannons
  const muzzles = [];
  const cannonRows = shipId === 'galleon' ? 4 : shipId === 'brig' ? 3 : 2;
  for (let side of [-1, 1]) {
    for (let i = 0; i < cannonRows; i++) {
      const z = 5.4 - i * 4.2;
      const cannon = new THREE.Mesh(new THREE.CylinderGeometry(0.26, 0.34, 1.5, 7), darkMat);
      cannon.rotation.z = Math.PI / 2;
      cannon.position.set(side * 3.5, 2.6, z);
      group.add(cannon);
      muzzles.push({ side, pos: new THREE.Vector3(side * 4.2, 2.7, z) });
    }
  }

  // lantern
  const lantern = new THREE.Mesh(new THREE.SphereGeometry(0.42, 8, 6), new THREE.MeshBasicMaterial({ color: 0xffc46b }));
  lantern.position.set(0, 6.9, -7.1);
  group.add(lantern);

  // decorative gold trim for higher classes
  if (shipId !== 'sloop') {
    const trim = new THREE.Mesh(new THREE.BoxGeometry(6.7, 0.25, 14.5), goldMat);
    trim.position.y = 2.1;
    group.add(trim);
  }

  group.userData = { sails, flag, muzzles, length: 19, shipId, lantern, masts };
  return group;
}

export function buildCaptain({ coat = 0x263a5c, hat = 0x1c1c22, skin = 0xd9a87a } = {}) {
  const group = new THREE.Group();
  const coatMat = new THREE.MeshLambertMaterial({ color: coat });
  const hatMat = new THREE.MeshLambertMaterial({ color: hat });
  const skinMat = new THREE.MeshLambertMaterial({ color: skin });
  const legMat = new THREE.MeshLambertMaterial({ color: 0x2a2a33 });

  const body = new THREE.Mesh(new THREE.CapsuleGeometry(0.62, 1.5, 4, 8), coatMat);
  body.position.y = 2.0;
  group.add(body);

  const head = new THREE.Mesh(new THREE.SphereGeometry(0.55, 12, 10), skinMat);
  head.position.y = 3.3;
  group.add(head);

  const brim = new THREE.Mesh(new THREE.CylinderGeometry(1.0, 1.0, 0.14, 12), hatMat);
  brim.position.y = 3.62;
  group.add(brim);
  const crown = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.62, 0.7, 10), hatMat);
  crown.position.y = 3.95;
  group.add(crown);

  const legs = [];
  for (const side of [-1, 1]) {
    const leg = new THREE.Mesh(new THREE.BoxGeometry(0.34, 1.3, 0.4), legMat);
    leg.position.set(side * 0.28, 0.7, 0);
    group.add(leg);
    legs.push(leg);
  }

  const arms = [];
  for (const side of [-1, 1]) {
    const arm = new THREE.Mesh(new THREE.CapsuleGeometry(0.16, 1.1, 3, 6), coatMat);
    arm.position.set(side * 0.78, 2.2, 0);
    arm.rotation.z = side * 0.12;
    group.add(arm);
    arms.push(arm);
  }

  group.userData = { legs, arms };
  group.scale.setScalar(0.78);
  return group;
}

export function buildCrate() {
  const group = new THREE.Group();
  const wood = new THREE.MeshLambertMaterial({ color: 0x7a5330 });
  const gold = new THREE.MeshLambertMaterial({ color: 0xffd479, emissive: 0x8a5a00, emissiveIntensity: 0.8 });
  const box = new THREE.Mesh(new THREE.BoxGeometry(2.4, 2.4, 2.4), wood);
  group.add(box);
  for (const y of [-1.21, 1.21]) {
    const band = new THREE.Mesh(new THREE.BoxGeometry(2.5, 0.18, 2.5), gold);
    band.position.y = y;
    group.add(band);
  }
  const glow = new THREE.Mesh(
    new THREE.SphereGeometry(3.4, 10, 8),
    new THREE.MeshBasicMaterial({ color: 0xffc46b, transparent: true, opacity: 0.16, depthWrite: false })
  );
  group.add(glow);
  group.userData.glow = glow;
  return group;
}

export function buildProjectile() {
  const geo = new THREE.SphereGeometry(0.42, 8, 6);
  const mat = new THREE.MeshBasicMaterial({ color: 0x222222 });
  return new THREE.Mesh(geo, mat);
}

import * as THREE from 'three';

const RING_GEO = new THREE.RingGeometry(0.82, 1, 36);
RING_GEO.rotateX(-Math.PI / 2);

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.items = [];
  }

  add(obj, ttl, update) {
    this.scene.add(obj);
    this.items.push({ obj, ttl, life: ttl, update });
    return obj;
  }

  ring(x, z, color = 0xbfe7ea, maxScale = 18, ttl = 0.9, y = 0.6) {
    const mat = new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: 0.75, depthWrite: false, side: THREE.DoubleSide
    });
    const mesh = new THREE.Mesh(RING_GEO, mat);
    mesh.position.set(x, y, z);
    mesh.scale.setScalar(1.5);
    this.add(mesh, ttl, (o, k) => {
      o.scale.setScalar(1.5 + (1 - k) * maxScale);
      o.material.opacity = 0.75 * k;
    });
  }

  splash(x, z, scale = 1) {
    this.ring(x, z, 0xd8f4f5, 16 * scale, 0.85);
    const count = 14;
    const geo = new THREE.BufferGeometry();
    const positions = new Float32Array(count * 3);
    const vel = [];
    for (let i = 0; i < count; i++) {
      positions[i * 3] = 0;
      positions[i * 3 + 1] = 0;
      positions[i * 3 + 2] = 0;
      const a = Math.random() * Math.PI * 2;
      const s = (2 + Math.random() * 5) * scale;
      vel.push(new THREE.Vector3(Math.sin(a) * s, 4 + Math.random() * 7, Math.cos(a) * s));
    }
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({
      color: 0xe8fbfb, size: 1.1 * scale, transparent: true, opacity: 0.9,
      depthWrite: false, blending: THREE.AdditiveBlending
    });
    const pts = new THREE.Points(geo, mat);
    pts.position.set(x, 0.6, z);
    const arr = geo.attributes.position.array;
    this.add(pts, 1.1, (o, k, dt) => {
      for (let i = 0; i < count; i++) {
        vel[i].y -= 14 * dt;
        arr[i * 3] += vel[i].x * dt;
        arr[i * 3 + 1] += vel[i].y * dt;
        arr[i * 3 + 2] += vel[i].z * dt;
      }
      o.geometry.attributes.position.needsUpdate = true;
      o.material.opacity = 0.9 * k;
    });
  }

  muzzle(x, y, z) {
    const mat = new THREE.MeshBasicMaterial({
      color: 0xffd28a, transparent: true, opacity: 1, depthWrite: false, blending: THREE.AdditiveBlending
    });
    const flash = new THREE.Mesh(new THREE.SphereGeometry(1.6, 8, 6), mat);
    flash.position.set(x, y, z);
    this.add(flash, 0.18, (o, k) => {
      o.scale.setScalar(1 + (1 - k) * 1.6);
      o.material.opacity = k;
    });
    this.ring(x, z, 0xffd28a, 5, 0.3, y);
  }

  explosion(x, z, color = 0xff8a3d) {
    this.ring(x, z, color, 26, 1.1);
    const mat = new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: 0.9, depthWrite: false, blending: THREE.AdditiveBlending
    });
    const ball = new THREE.Mesh(new THREE.SphereGeometry(3, 10, 8), mat);
    ball.position.set(x, 3, z);
    this.add(ball, 0.55, (o, k) => {
      o.scale.setScalar(1 + (1 - k) * 2.4);
      o.material.opacity = k * 0.9;
    });
    this.splash(x, z, 1.4);
  }

  ability(x, z, color) {
    this.ring(x, z, color, 44, 1.4);
    this.ring(x, z, color, 26, 1.0);
  }

  update(dt) {
    for (let i = this.items.length - 1; i >= 0; i--) {
      const item = this.items[i];
      item.life -= dt;
      const k = Math.max(0, item.life / item.ttl);
      if (item.update) item.update(item.obj, k, dt);
      if (item.life <= 0) {
        this.scene.remove(item.obj);
        if (item.obj.geometry) item.obj.geometry.dispose?.();
        if (item.obj.material) {
          if (Array.isArray(item.obj.material)) item.obj.material.forEach((m) => m.dispose?.());
          else item.obj.material.dispose?.();
        }
        this.items.splice(i, 1);
      }
    }
  }
}

// Tiny procedural sound engine - no audio assets needed.
export class Audio {
  constructor() {
    this.ctx = null;
    this.enabled = true;
    this.master = null;
    this.ambient = null;
  }

  init() {
    if (this.ctx) return;
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.5;
    this.master.connect(this.ctx.destination);
    this.startAmbient();
  }

  resume() {
    if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume();
  }

  setEnabled(on) {
    this.enabled = on;
    if (this.master) this.master.gain.value = on ? 0.5 : 0;
  }

  noiseBuffer(seconds = 1) {
    const rate = this.ctx.sampleRate;
    const buf = this.ctx.createBuffer(1, rate * seconds, rate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
    return buf;
  }

  startAmbient() {
    if (!this.ctx || this.ambient) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer(3);
    src.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 420;
    const gain = this.ctx.createGain();
    gain.gain.value = 0.055;
    src.connect(filter).connect(gain).connect(this.master);
    src.start();
    this.ambient = { src, gain, filter };
    // slow swell
    const lfo = this.ctx.createOscillator();
    lfo.frequency.value = 0.09;
    const lfoGain = this.ctx.createGain();
    lfoGain.gain.value = 0.03;
    lfo.connect(lfoGain).connect(gain.gain);
    lfo.start();
  }

  tone(freq, duration, type = 'sine', gainValue = 0.2, slide = 0) {
    if (!this.ctx || !this.enabled) return;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, this.ctx.currentTime);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), this.ctx.currentTime + duration);
    gain.gain.setValueAtTime(gainValue, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + duration);
    osc.connect(gain).connect(this.master);
    osc.start();
    osc.stop(this.ctx.currentTime + duration);
  }

  noise(duration = 0.4, freq = 800, q = 1, gainValue = 0.25, type = 'lowpass') {
    if (!this.ctx || !this.enabled) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer(Math.max(0.2, duration));
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, this.ctx.currentTime);
    filter.frequency.exponentialRampToValueAtTime(Math.max(60, freq * 0.35), this.ctx.currentTime + duration);
    filter.Q.value = q;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(gainValue, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + duration);
    src.connect(filter).connect(gain).connect(this.master);
    src.start();
    src.stop(this.ctx.currentTime + duration);
  }

  cannon() {
    this.noise(0.5, 900, 0.8, 0.4);
    this.tone(120, 0.35, 'sine', 0.32, -70);
  }

  hit() {
    this.noise(0.25, 1400, 1, 0.22);
    this.tone(220, 0.18, 'square', 0.06, -80);
  }

  splash() {
    this.noise(0.4, 1800, 0.7, 0.14, 'highpass');
  }

  pickup() {
    this.tone(660, 0.14, 'triangle', 0.15);
    setTimeout(() => this.tone(990, 0.22, 'triangle', 0.13), 80);
  }

  levelup() {
    [523, 659, 784, 1047].forEach((f, i) => {
      setTimeout(() => this.tone(f, 0.35, 'triangle', 0.14), i * 110);
    });
  }

  click() {
    this.tone(420, 0.06, 'sine', 0.05);
  }

  error() {
    this.tone(150, 0.18, 'sawtooth', 0.06, -40);
  }
}

:root {
  --ink: #04141a;
  --deep: #08242e;
  --panel: rgba(6, 24, 30, 0.82);
  --panel-solid: #0a2129;
  --line: rgba(232, 200, 122, 0.28);
  --gold: #e8c87a;
  --gold-bright: #ffdd93;
  --cream: #f4ecd9;
  --muted: #93aeb4;
  --teal: #2f8f83;
  --teal-bright: #54c7b5;
  --red: #d9604d;
  --green: #7fdc8f;
  --purple: #b48cff;
  --shadow: 0 18px 50px rgba(0, 0, 0, 0.45);
  --r: 14px;
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--cream);
  font-family: "Segoe UI", system-ui, -apple-system, "Helvetica Neue", sans-serif;
  overscroll-behavior: none;
}

body { user-select: none; }

#scene { position: fixed; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }

#vignette {
  position: fixed; inset: 0; pointer-events: none; z-index: 1;
  background:
    linear-gradient(180deg, rgba(2, 10, 14, 0.62) 0%, rgba(2, 10, 14, 0) 22%, rgba(2, 10, 14, 0) 72%, rgba(2, 10, 14, 0.55) 100%),
    radial-gradient(120% 90% at 50% 50%, rgba(0,0,0,0) 55%, rgba(1, 8, 11, 0.45) 100%);
}

.hidden { display: none !important; }

kbd {
  font-family: inherit; font-size: 10px; font-weight: 700; letter-spacing: 0.04em;
  padding: 2px 5px; border-radius: 4px; border: 1px solid rgba(244, 236, 217, 0.3);
  background: rgba(255, 255, 255, 0.08); color: var(--cream);
}

/* ------------------------------- glass ------------------------------- */
.glass {
  background: linear-gradient(180deg, rgba(8, 30, 37, 0.8), rgba(4, 18, 23, 0.86));
  border: 1px solid var(--line);
  border-radius: var(--r);
  box-shadow: var(--shadow);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}
.glass-strong {
  background: linear-gradient(180deg, rgba(9, 33, 41, 0.94), rgba(4, 16, 21, 0.96));
  border: 1px solid rgba(232, 200, 122, 0.34);
  border-radius: 20px;
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

/* ------------------------------ loading ------------------------------ */
#loading {
  position: fixed; inset: 0; z-index: 100; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 12px;
  background: radial-gradient(80% 80% at 50% 40%, #0b2c36 0%, #04141a 70%);
