}
#loading.done { opacity: 0; pointer-events: none; }
.loading-mark { font-size: 44px; animation: bob 2s ease-in-out infinite; }
.loading-title { font-family: Georgia, serif; letter-spacing: 0.42em; font-size: 20px; color: var(--gold); }
.loading-bar { width: 220px; height: 3px; background: rgba(255,255,255,0.1); border-radius: 3px; overflow: hidden; }
