#hud-bottom { position: absolute; left: 50%; bottom: calc(16px + var(--safe-b)); transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 10px; }
#abilities { display: flex; gap: 9px; }
.ability {
  position: relative; width: 60px; height: 60px; border-radius: 12px; cursor: pointer;
  border: 1px solid var(--line); color: var(--cream); font-size: 24px;
