// Multiplayer + account client. Everything degrades gracefully to offline play.
export class Net {
  constructor() {
    this.ws = null;
    this.id = null;
    this.connected = false;
    this.online = 1;
    this.players = new Map();
    this.npcs = new Map();
    this.loot = new Map();
    this.handlers = new Map();
    this.token = localStorage.getItem('kaperfahrt.token') || null;
    this.accountName = localStorage.getItem('kaperfahrt.account') || null;
    this.lastError = null;
    this.retry = 0;
  }

  on(type, fn) {
    if (!this.handlers.has(type)) this.handlers.set(type, []);
    this.handlers.get(type).push(fn);
  }

  emit(type, payload) {
    for (const fn of this.handlers.get(type) || []) {
      try { fn(payload); } catch (e) { console.error(e); }
    }
  }

  url(path) {
    const proto = location.protocol === 'https:' ? 'wss' : 'ws';
    return `${proto}://${location.host}${path}`;
  }

  connect(profile) {
    return new Promise((resolve) => {
      if (this.ws) { try { this.ws.close(); } catch {} }
      let settled = false;
      const done = (ok) => { if (!settled) { settled = true; resolve(ok); } };
      let ws;
      try {
        ws = new WebSocket(this.url('/ws'));
      } catch {
        done(false);
        return;
      }
      this.ws = ws;
      const timeout = setTimeout(() => { if (!this.connected) { try { ws.close(); } catch {} done(false); } }, 3500);

      ws.onopen = () => {
        this.connected = true;
        clearTimeout(timeout);
        this.retry = 0;
        this.send({ t: 'join', ...profile });
        done(true);
      };
      ws.onmessage = (ev) => {
        let msg;
        try { msg = JSON.parse(ev.data); } catch { return; }
        this.handle(msg);
      };
      ws.onclose = () => {
        this.connected = false;
        clearTimeout(timeout);
        this.emit('disconnect');
        done(false);
      };
      ws.onerror = () => {
        this.lastError = 'Verbindung fehlgeschlagen';
        done(false);
      };
    });
  }

  handle(msg) {
    switch (msg.t) {
      case 'welcome':
        this.id = msg.id;
        this.players.clear();
        for (const p of msg.players) this.players.set(p.id, p);
        this.players.set(msg.self.id, msg.self);
        this.npcs.clear();
        for (const n of msg.snapshot.npcs) this.npcs.set(n.id, n);
        this.loot.clear();
        for (const l of msg.snapshot.loot) this.loot.set(l.id, l);
        this.online = msg.online;
        this.emit('welcome', msg);
        break;
      case 'snapshot': {
        this.online = msg.online;
        this.players.clear();
        for (const p of msg.players) this.players.set(p.id, p);
        this.npcs.clear();
        for (const n of msg.npcs) this.npcs.set(n.id, n);
        this.loot.clear();
        for (const l of msg.loot) this.loot.set(l.id, l);
        this.emit('snapshot', msg);
        break;
      }
      case 'joined':
        this.players.set(msg.player.id, msg.player);
        this.emit('joined', msg.player);
        break;
      case 'left':
        this.players.delete(msg.id);
        this.emit('left', msg.id);
        break;
      case 'event':
        this.emit('event', msg);
        break;
      case 'reward':
        this.emit('reward', msg);
        break;
      case 'hit':
        this.emit('hit', msg);
        break;
      case 'levelup':
        this.emit('levelup', msg);
        break;
      case 'chat':
        this.emit('chat', msg);
        break;
      case 'online':
        this.online = msg.count;
        this.emit('online', msg.count);
        break;
      case 'pong':
        this.emit('pong', msg);
        break;
    }
  }

  send(msg) {
    if (this.ws && this.ws.readyState === 1) this.ws.send(JSON.stringify(msg));
    return this.ws && this.ws.readyState === 1;
  }

  disconnect() {
    if (this.ws) { try { this.ws.close(); } catch {} }
    this.ws = null;
    this.connected = false;
    this.id = null;
  }

  async api(path, options = {}) {
    const headers = { 'content-type': 'application/json', ...(options.headers || {}) };
    if (this.token) headers.authorization = `Bearer ${this.token}`;
    const res = await fetch(path, { ...options, headers });
    let body = null;
    try { body = await res.json(); } catch {}
    if (!res.ok) throw new Error(body?.error || `HTTP ${res.status}`);
    return body;
  }

  async register(name, password) {
    const res = await this.api('/api/register', { method: 'POST', body: JSON.stringify({ name, password }) });
    this.token = res.token;
    this.accountName = res.name;
    localStorage.setItem('kaperfahrt.token', res.token);
    localStorage.setItem('kaperfahrt.account', res.name);
    return res;
  }

  async login(name, password) {
    const res = await this.api('/api/login', { method: 'POST', body: JSON.stringify({ name, password }) });
    this.token = res.token;
    this.accountName = res.name;
    localStorage.setItem('kaperfahrt.token', res.token);
    localStorage.setItem('kaperfahrt.account', res.name);
    return res;
  }

  async saveCloud(profile) {
    return this.api('/api/save', { method: 'PUT', body: JSON.stringify({ profile }) });
  }

  async loadCloud() {
    const res = await this.api('/api/save');
    return res.profile;
  }

  logout() {
    this.token = null;
    this.accountName = null;
    localStorage.removeItem('kaperfahrt.token');
    localStorage.removeItem('kaperfahrt.account');
  }
}

import * as THREE from 'three';
import { RARITY, levelFromXp, xpForLevel } from './shared/rules.js';

export const FACTIONS = {
  pirate: { label: 'Piraten', icon: '☠', color: '#d9604d', bonus: '+10% Gold aus Beute', desc: 'Freiheit, Beute, schlechter Ruf.' },
  marine: { label: 'Marine', icon: '⚓', color: '#8fd0ff', bonus: '+15% Hüllen-HP', desc: 'Disziplin, Orden, zu viele Vorschriften.' },
  merchant: { label: 'Händler', icon: '⚖', color: '#e8c87a', bonus: '+20% Verkaufspreis', desc: 'Frieden ist gut fürs Geschäft.' },
  temple: { label: 'Tempelorden', icon: '☯', color: '#b48cff', bonus: '+1 Start-Skillpunkt', desc: 'Die Urkraft ist kein Werkzeug.' },
  blackmarket: { label: 'Schwarzer Markt', icon: '🕯', color: '#c08cff', bonus: '+150 Startgold', desc: 'Keine Fragen. Nur Preise.' }
};

const SERVICE_LABEL = {
  market: { icon: '🏪', label: 'Hafenmarkt', desc: 'Vorräte kaufen und Beute verkaufen.' },
  blackmarket: { icon: '🕯', label: 'Schwarzer Markt', desc: 'Seltene Ware, keine Quittungen.' },
  shipwright: { icon: '🔨', label: 'Werft', desc: 'Reparieren, aufrüsten, neue Schiffe.' },
  tavern: { icon: '🍺', label: 'Taverne', desc: 'Heilen, Gerüchte, ein Glas Rum.' },
  quests: { icon: '📜', label: 'Auftragsbrett', desc: 'Aufträge annehmen und Belohnungen kassieren.' },
  shrine: { icon: '🏮', label: 'Urkraft-Schrein', desc: 'Eine neue Frucht wählen.' }
};

const ABILITY_ICONS = {
  windschnitt: '🌪️', sturmfaust: '💨', aufwind: '⛵',
  lavakugel: '🔥', vulkanausbruch: '🌋', glutpanzer: '🛡️',
  schattenritt: '🌑', seelenfeuer: '🔮', nebelhort: '🌫️'
};

const TITLES = [
  [1, 'Neuling der See'], [3, 'Küstenläufer'], [6, 'Freibeuter'], [10, 'Kapitän'],
  [15, 'Sturmsegler'], [20, 'Legende'], [30, 'Herr der Gezeiten']
];

function esc(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

function fmt(n) {
  return Math.round(n).toLocaleString('de-DE');
}

export class UI {
  constructor(game) {
    this.game = game;
    this.el = {};
    for (const id of [
      'hud', 'hud-name', 'hud-level', 'hud-faction', 'hud-title', 'hud-hp-fill', 'hud-hp-text',
      'hud-xp-fill', 'hud-xp-text', 'hud-gold', 'hud-bounty', 'hud-speed', 'hud-heading',
      'hud-throttle', 'hud-crest', 'online-count', 'minimap', 'quest-name', 'quest-text',
      'quest-progress', 'abilities', 'chat-log', 'chat-input', 'chat-form', 'toasts',
      'dock-prompt', 'dock-label', 'dock-btn', 'nameplates', 'start-screen', 'panel-layer',
      'panel', 'panel-title', 'panel-kicker', 'panel-body', 'panel-close', 'loading',
      'loading-fill', 'loading-text', 'edit-name', 'faction-picker', 'fruit-picker',
      'ship-picker', 'start-btn', 'continue-btn', 'account-btn', 'btn-map', 'btn-inventory',
      'btn-skills', 'btn-menu', 'joystick', 'joystick-knob', 'touch-fire', 'touch-interact',
      'touch-map', 'mobile-controls'
    ]) {
      this.el[id] = document.getElementById(id);
    }
    this.panel = null;
    this.panelStack = [];
    this.toastTimer = 0;
    this.hudTimer = 0;
    this.minimapTimer = 0;
    this.plateTimer = 0;
    this.draft = { faction: 'pirate', fruitId: 'kaze', shipId: 'sloop' };
    this.chatLines = [];
    this.plates = new Map();
    this.mmCtx = this.el.minimap.getContext('2d');
    this.abilityButtons = [];
    this.wire();
  }

  wire() {
    this.el['panel-close'].addEventListener('click', () => this.closePanel());
    this.el['panel-layer'].addEventListener('mousedown', (e) => {
      if (e.target === this.el['panel-layer']) this.closePanel();
    });
    this.el['panel-body'].addEventListener('click', (e) => {
      const btn = e.target.closest('[data-act]');
      if (!btn || btn.disabled) return;
      this.game.audio.click();
      this.handleAction(btn.dataset.act, btn.dataset);
    });
    this.el['chat-form'].addEventListener('submit', (e) => {
      e.preventDefault();
      const text = this.el['chat-input'].value.trim();
      if (text) this.game.sendChat(text);
      this.el['chat-input'].value = '';
      this.el['chat-input'].blur();
    });
    this.el['chat-input'].addEventListener('keydown', (e) => e.stopPropagation());
    this.el['dock-btn'].addEventListener('click', () => this.game.interact());
    this.el['btn-map'].addEventListener('click', () => this.openMap());
    this.el['btn-inventory'].addEventListener('click', () => this.openInventory());
    this.el['btn-skills'].addEventListener('click', () => this.openSkills());
    this.el['btn-menu'].addEventListener('click', () => this.openMenu());
    this.el['touch-map'].addEventListener('click', () => this.openMap());
    this.el['touch-interact'].addEventListener('click', () => this.game.interact());
    this.el['touch-fire'].addEventListener('pointerdown', (e) => { e.preventDefault(); this.game.fire(); });
    document.querySelectorAll('.ability-touch').forEach((btn) => {
      btn.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        this.game.useAbility(Number(btn.dataset.slot));
      });
    });
    this.el['start-btn'].addEventListener('click', () => this.game.startNew(this.draft, this.el['edit-name'].value));
    this.el['continue-btn'].addEventListener('click', () => this.game.loadSave());
    this.el['account-btn'].addEventListener('click', () => this.openAccount());
    this.el['edit-name'].addEventListener('keydown', (e) => {
      e.stopPropagation();
      if (e.key === 'Enter') this.el['start-btn'].click();
    });
  }

  /* ------------------------------- start ------------------------------- */

  showStart(hasSave) {
    this.el['start-screen'].classList.remove('hidden');
    this.el.hud.classList.add('hidden');
    this.el['continue-btn'].classList.toggle('hidden', !hasSave);
    const saved = this.game.loadedProfile;
    this.el['edit-name'].value = saved?.name || this.el['edit-name'].value || '';
    this.draft.faction = saved?.faction || this.draft.faction;
    this.draft.fruitId = saved?.fruitId || this.draft.fruitId;
    this.renderEditor();
  }

  hideStart() {
    this.el['start-screen'].classList.add('hidden');
    this.el.hud.classList.remove('hidden');
  }

  renderEditor() {
    const { factions, fruits, ships } = this.game.data;
    this.el['faction-picker'].innerHTML = Object.entries(FACTIONS).map(([id, f]) => `
      <button class="card ${this.draft.faction === id ? 'selected' : ''}" data-faction="${id}">
        <span class="c-icon">${f.icon}</span>
        <span class="c-name">${f.label}</span>
        <span class="c-sub">${f.bonus}</span>
      </button>`).join('');
    this.el['fruit-picker'].innerHTML = fruits.map((f) => `
      <button class="card ${this.draft.fruitId === f.id ? 'selected' : ''}" data-fruit="${f.id}">
        <span class="c-icon" style="color:${f.color}">✦</span>
        <span class="c-name">${f.name}</span>
        <span class="c-sub">${f.element}</span>
        <span class="c-desc">${f.passive}</span>
      </button>`).join('');
    this.el['ship-picker'].innerHTML = ships.playerShips.map((s) => `
      <button class="card ${this.draft.shipId === s.id ? 'selected' : ''}" data-ship="${s.id}">
        <span class="c-icon">⛵</span>
        <span class="c-name">${s.name}</span>
        <span class="c-sub">${s.class} · ${s.hp} HP</span>
        <span class="c-desc">${s.price ? `ab ${fmt(s.price)} Gold` : 'Startschiff'}</span>
      </button>`).join('');

    this.el['faction-picker'].querySelectorAll('[data-faction]').forEach((b) => {
      b.onclick = () => { this.draft.faction = b.dataset.faction; this.renderEditor(); };
    });
    this.el['fruit-picker'].querySelectorAll('[data-fruit]').forEach((b) => {
      b.onclick = () => { this.draft.fruitId = b.dataset.fruit; this.renderEditor(); };
    });
    this.el['ship-picker'].querySelectorAll('[data-ship]').forEach((b) => {
      b.onclick = () => {
        const ship = this.game.data.ships.playerShips.find((s) => s.id === b.dataset.ship);
        if (ship.price > 250) { this.toast(`${ship.name} kostet ${fmt(ship.price)} Gold – später in der Werft.`, 'danger', '🔒'); return; }
        this.draft.shipId = b.dataset.ship;
        this.renderEditor();
      };
    });
  }

  /* -------------------------------- HUD -------------------------------- */

  setOnline(n) {
    this.el['online-count'].textContent = n ?? 1;
  }

  updateHUD(dt) {
    this.hudTimer -= dt;
    if (this.hudTimer > 0) return;
    this.hudTimer = 0.12;
    const g = this.game;
    const s = g.state;
    if (!s) return;
    const info = levelFromXp(s.xp);
    this.el['hud-name'].textContent = s.name;
    this.el['hud-level'].textContent = `Lv ${info.level}`;
    this.el['hud-faction'].textContent = FACTIONS[s.faction]?.label || 'Piraten';
    this.el['hud-crest'].textContent = FACTIONS[s.faction]?.icon || '☠';
    let title = 'Neuling der See';
    for (const [lv, t] of TITLES) if (info.level >= lv) title = t;
    this.el['hud-title'].textContent = title;
    const maxHp = g.maxHp();
    const hp = Math.max(0, Math.round(s.hp));
    this.el['hud-hp-fill'].style.width = `${Math.max(0, Math.min(100, (hp / maxHp) * 100))}%`;
    this.el['hud-hp-text'].textContent = `${hp} / ${maxHp}`;
    this.el['hud-xp-fill'].style.width = `${Math.min(100, (info.rest / info.need) * 100)}%`;
    this.el['hud-xp-text'].textContent = `${fmt(info.rest)} / ${fmt(info.need)} XP`;
    this.el['hud-gold'].textContent = fmt(s.gold);
    this.el['hud-bounty'].textContent = fmt(s.bounty);
    this.el['hud-speed'].textContent = `${Math.round(Math.abs(g.speed) * 0.55)} kn`;
    const deg = ((g.rot * 180 / Math.PI) % 360 + 360) % 360;
    const dirs = ['N', 'NO', 'O', 'SO', 'S', 'SW', 'W', 'NW'];
    this.el['hud-heading'].textContent = `${dirs[Math.round(deg / 45) % 8]} ${String(Math.round(deg)).padStart(3, '0')}°`;
    this.el['hud-throttle'].style.width = `${Math.abs(g.throttle) * 100}%`;
    this.setOnline(g.net?.connected ? g.net.online : 1);

    // quest tracker
    const active = s.quests.find((q) => !q.done);
    if (active) {
      const def = this.game.data.quests.find((q) => q.id === active.id);
      if (def) {
        this.el['quest-name'].textContent = def.name;
        this.el['quest-text'].textContent = def.text;
        this.el['quest-progress'].classList.remove('hidden');
        this.el['quest-progress'].querySelector('b').textContent = `${Math.min(active.progress, def.count)} / ${def.count}`;
        this.el['quest-progress'].querySelector('i').style.setProperty('--p', `${Math.min(100, (active.progress / def.count) * 100)}%`);
      }
    } else {
      this.el['quest-name'].textContent = 'Kein Auftrag';
      this.el['quest-text'].textContent = 'Sprich am Auftragsbrett in einem Hafen vor.';
      this.el['quest-progress'].classList.add('hidden');
    }

    this.updateAbilities();
    this.drawMinimap();
  }

  renderAbilities() {
    const fruit = this.game.fruitDef();
    if (!fruit) return;
    this.el.abilities.innerHTML = fruit.abilities.map((a, i) => `
      <button class="ability" data-slot="${i}" title="${esc(a.name)} – ${esc(a.desc)}">
        <span class="key">${i + 1}</span>
        <span class="ico">${ABILITY_ICONS[a.id] || '✦'}</span>
        <span class="cd" style="--p:0"></span>
        <span class="cdtext"></span>
      </button>`).join('');
    this.abilityButtons = [...this.el.abilities.querySelectorAll('.ability')];
    this.abilityButtons.forEach((btn, i) => btn.addEventListener('click', () => this.game.useAbility(i)));
    document.querySelectorAll('.ability-touch').forEach((btn, i) => {
      btn.textContent = ABILITY_ICONS[fruit.abilities[i]?.id] || (i + 1);
    });
  }

  updateAbilities() {
    const fruit = this.game.fruitDef();
    if (!fruit) return;
    const now = performance.now() / 1000;
    fruit.abilities.forEach((a, i) => {
      const btn = this.abilityButtons[i];
      if (!btn) return;
      const readyAt = this.game.abilityReady[i] || 0;
      const left = Math.max(0, readyAt - now);
      const pct = left > 0 ? (left / a.cooldown) * 100 : 0;
      btn.querySelector('.cd').style.setProperty('--p', pct);
      const cdtext = btn.querySelector('.cdtext');
      cdtext.textContent = left > 0 ? Math.ceil(left) : '';
      btn.classList.toggle('ready', left <= 0);
      const touch = document.querySelectorAll('.ability-touch')[i];
      if (touch) touch.classList.toggle('cooling', left > 0);
    });
  }

  promptDock(island) {
    if (island) {
      this.el['dock-prompt'].classList.remove('hidden');
      this.el['dock-label'].textContent = `In ${island.name} anlegen`;
    } else {
      this.el['dock-prompt'].classList.add('hidden');
    }
  }

  toast(text, kind = '', icon = '') {
    const div = document.createElement('div');
    div.className = `toast ${kind}`;
    div.innerHTML = `${icon ? `<span>${icon}</span>` : ''}<span>${esc(text)}</span>`;
    this.el.toasts.appendChild(div);
    while (this.el.toasts.children.length > 4) this.el.toasts.firstChild.remove();
    setTimeout(() => {
      div.classList.add('out');
      setTimeout(() => div.remove(), 420);
    }, 3000);
  }

  chat(from, text, faction = 'neutral', sys = false) {
    const div = document.createElement('div');
    if (sys) {
      div.className = 'sys';
      div.textContent = text;
    } else {
      div.innerHTML = `<b style="color:${FACTIONS[faction]?.color || '#54c7b5'}">${esc(from)}</b> ${esc(text)}`;
    }
    this.el['chat-log'].appendChild(div);
    while (this.el['chat-log'].children.length > 40) this.el['chat-log'].firstChild.remove();
    this.el['chat-log'].scrollTop = this.el['chat-log'].scrollHeight;
  }

  /* ---------------------------- nameplates ---------------------------- */

  updateNameplates(dt) {
    this.plateTimer -= dt;
    if (this.plateTimer > 0) return;
    this.plateTimer = 0.06;
    const g = this.game;
    const camera = g.camera;
    const w = window.innerWidth;
    const h = window.innerHeight;
    const seen = new Set();
    const entities = [];
    for (const n of g.getNpcs()) {
      if (!n.alive) continue;
      const d = Math.hypot(n.x - g.pos.x, n.z - g.pos.z);
      if (d < 620) entities.push({ ...n, kind: n.boss ? 'boss' : 'hostile', y: 12 });
    }
    if (g.net?.connected) {
      for (const p of g.net.players.values()) {
        if (p.id === g.net.id) continue;
        const d = Math.hypot(p.x - g.pos.x, p.z - g.pos.z);
        if (d < 620) entities.push({ ...p, kind: 'player', y: 12 });
      }
    }
    for (const e of entities) {
      const v = new THREE.Vector3(e.x, e.y, e.z).project(camera);
      if (v.z > 1 || v.z < -1) continue;
      const sx = (v.x * 0.5 + 0.5) * w;
      const sy = (-v.y * 0.5 + 0.5) * h;
      if (sx < -80 || sx > w + 80 || sy < 0 || sy > h) continue;
      seen.add(e.id);
      let div = this.plates.get(e.id);
      if (!div) {
        div = document.createElement('div');
        div.className = `nameplate ${e.kind}`;
        div.innerHTML = `<span class="np-name"></span><span class="np-bar"><i></i></span>`;
        this.el.nameplates.appendChild(div);
        this.plates.set(e.id, div);
      }
      div.style.transform = `translate3d(${sx}px, ${sy}px, 0) translate(-50%, -50%)`;
      div.querySelector('.np-name').textContent = e.kind === 'player' ? e.name : `${e.name}${e.level ? ` · Lv ${e.level}` : ''}`;
      const bar = div.querySelector('.np-bar i');
      if (e.kind === 'player') bar.style.display = 'none';
      else {
        bar.style.display = 'block';
        bar.style.width = `${Math.max(0, (e.hp / e.maxHp) * 100)}%`;
      }
    }
    for (const [id, div] of this.plates) {
      if (!seen.has(id)) { div.remove(); this.plates.delete(id); }
    }
  }

  /* ------------------------------ minimap ------------------------------ */

  drawMinimap() {
    const g = this.game;
    const ctx = this.mmCtx;
    const size = 440;
    const cx = size / 2;
    const cy = size / 2;
    const scale = size / 1900;
    ctx.clearRect(0, 0, size, size);
    const grad = ctx.createRadialGradient(cx, cy, 10, cx, cy, cx);
    grad.addColorStop(0, 'rgba(12, 58, 70, 0.96)');
    grad.addColorStop(1, 'rgba(4, 22, 29, 0.98)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(cx, cy, cx - 2, 0, Math.PI * 2);
    ctx.fill();
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, cx - 2, 0, Math.PI * 2);
    ctx.clip();

    const toMap = (x, z) => [cx + (x - g.pos.x) * scale, cy + (z - g.pos.z) * scale];

    for (const isl of g.data.islands) {
      const [x, y] = toMap(isl.x, isl.z);
      if (x < -80 || x > size + 80 || y < -80 || y > size + 80) continue;
      ctx.beginPath();
      ctx.arc(x, y, Math.max(3, isl.radius * scale), 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(232, 200, 122, 0.28)';
      ctx.fill();
      ctx.strokeStyle = 'rgba(232, 200, 122, 0.55)';
      ctx.lineWidth = 1.5;
      ctx.stroke();
      if (isl.radius * scale > 7) {
        ctx.fillStyle = 'rgba(244, 236, 217, 0.8)';
        ctx.font = '16px Georgia, serif';
        ctx.textAlign = 'center';
        ctx.fillText(isl.name.split(' ')[0], x, y + 5);
      }
    }

    for (const l of g.getLoot()) {
      const [x, y] = toMap(l.x, l.z);
      ctx.fillStyle = '#ffd479';
      ctx.fillRect(x - 3, y - 3, 6, 6);
    }
    for (const n of g.getNpcs()) {
      if (!n.alive) continue;
      const [x, y] = toMap(n.x, n.z);
      if (x < 0 || x > size || y < 0 || y > size) continue;
      ctx.beginPath();
      ctx.arc(x, y, n.boss ? 8 : 4.5, 0, Math.PI * 2);
      ctx.fillStyle = n.boss ? '#c08cff' : n.faction === 'marine' ? '#8fd0ff' : '#ff8f7a';
      ctx.fill();
    }
    if (g.net?.connected) {
      for (const p of g.net.players.values()) {
        if (p.id === g.net.id) continue;
        const [x, y] = toMap(p.x, p.z);
        ctx.beginPath();
        ctx.arc(x, y, 4.5, 0, Math.PI * 2);
        ctx.fillStyle = '#54c7b5';
        ctx.fill();
      }
    }
    if (g.waypoint) {
      const [x, y] = toMap(g.waypoint.x, g.waypoint.z);
      ctx.strokeStyle = '#e8c87a';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(x - 8, y - 8); ctx.lineTo(x + 8, y + 8);
      ctx.moveTo(x + 8, y - 8); ctx.lineTo(x - 8, y + 8);
      ctx.stroke();
    }

    // player arrow
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(-g.rot + Math.PI);
    ctx.beginPath();
    ctx.moveTo(0, -12);
    ctx.lineTo(8, 9);
    ctx.lineTo(0, 4);
    ctx.lineTo(-8, 9);
    ctx.closePath();
    ctx.fillStyle = '#f4ecd9';
    ctx.fill();
    ctx.strokeStyle = '#0a2530';
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.restore();
    ctx.restore();
  }

  /* ------------------------------- panels ------------------------------ */

  openPanel(kind, island = null, extra = {}) {
    this.panel = { kind, island, ...extra };
    this.el['panel-layer'].classList.remove('hidden');
    this.renderPanel();
  }

  closePanel() {
    this.panel = null;
    this.el['panel-layer'].classList.add('hidden');
    this.el['panel-body'].innerHTML = '';
    this.game.panelOpen = false;
    if (this.el['chat-input'] !== document.activeElement) this.game.audio.resume();
  }

  renderPanel() {
    if (!this.panel) return;
    const { kind, island } = this.panel;
    const map = {
      harbor: () => this.panelHarbor(island),
      market: () => this.panelMarket(island, 'market'),
      blackmarket: () => this.panelMarket(island, 'blackmarket'),
      shipyard: () => this.panelShipyard(island),
      tavern: () => this.panelTavern(island),
      shrine: () => this.panelShrine(island),
      quests: () => this.panelQuests(island),
      inventory: () => this.panelInventory(),
      skills: () => this.panelSkills(),
      map: () => this.panelMap(),
      menu: () => this.panelMenu(),
      account: () => this.panelAccount(),
      controls: () => this.panelControls(),
      settings: () => this.panelMenu()
    };
    const result = (map[kind] || (() => ({ title: 'Unbekannt', kicker: '', body: '<p>Nichts hier.</p>' })))();
    this.el['panel-title'].textContent = result.title;
    this.el['panel-kicker'].textContent = result.kicker || '';
    this.el['panel-body'].innerHTML = result.body;
    this.game.panelOpen = true;
    if (result.after) result.after();
  }

  refresh() {
    if (this.panel) this.renderPanel();
  }

  metaRow(island) {
    const f = FACTIONS[island.faction] || FACTIONS.neutral;
    return `<div class="map-legend" style="margin:0 0 14px">
      <span><i style="background:${f.color}"></i>${f.label}</span>
      <span>🏝️ ${esc(island.type)}</span>
      <span>⚔️ Empfohlen Lv ${island.level}</span>
      <span>📦 ${island.resources.join(', ')}</span>
    </div>`;
  }

  panelHarbor(island) {
    if (!island) return { title: 'Hafen', kicker: 'Anlegen', body: '<p>Kein Hafen in Reichweite.</p>' };
    const services = island.services.map((s) => {
      const meta = SERVICE_LABEL[s];
      if (!meta) return '';
      return `<button class="service-btn" data-act="service" data-service="${s}">
        <b>${meta.icon} ${meta.label}</b><span>${meta.desc}</span></button>`;
    }).join('');
    return {
      title: island.name,
      kicker: 'Hafen · Angedockt',
      body: `
        <p class="lead">„${esc(island.description)}“</p>
        ${this.metaRow(island)}
        <div class="service-grid">${services}
          <button class="service-btn" data-act="set-waypoint" data-island="${island.id}">
            <b>🧭 Kurs setzen</b><span>Markiert die Insel auf Karte und Minimap.</span></button>
          <button class="service-btn" data-act="undock">
            <b>⚓ Ablegen</b><span>Zurück auf die offene See.</span></button>
        </div>`
    };
  }

  panelMarket(island, service) {
    const s = this.game.state;
    const npc = this.game.data.npcs[service] || this.game.data.npcs.market;
    const stock = npc.stock || [];
    const buyRows = stock.map((id) => {
      const item = this.game.itemDef(id);
      if (!item) return '';
      const price = this.game.buyPrice(item, service);
      return `<div class="item-row rarity-${item.rarity}">
        <span class="i-ico">${item.icon}</span>
        <div class="i-main"><div class="i-name">${esc(item.name)}</div>
        <div class="i-sub">${RARITY[item.rarity]?.label || ''} · ${esc(item.desc)}</div></div>
        <span class="i-price">${fmt(price)} 🪙</span>
        <button data-act="buy" data-item="${id}" data-service="${service}" ${s.gold < price ? 'disabled' : ''}>Kaufen</button>
      </div>`;
    }).join('');
    const inv = Object.entries(s.inventory).filter(([, c]) => c > 0);
    const sellRows = inv.map(([id, count]) => {
      const item = this.game.itemDef(id);
      if (!item || item.type === 'fruit') return '';
      const price = this.game.sellPrice(item);
      return `<div class="item-row rarity-${item.rarity}">
        <span class="i-ico">${item.icon}</span>
        <div class="i-main"><div class="i-name">${esc(item.name)} <span class="i-sub">×${count}</span></div>
        <div class="i-sub">Verkaufswert ${fmt(price)} 🪙</div></div>
        <button data-act="sell" data-item="${id}" data-service="${service}" data-count="1">1 verkaufen</button>
        <button data-act="sell" data-item="${id}" data-service="${service}" data-count="${count}">Alle</button>
      </div>`;
    }).join('');
    return {
      title: npc.name || 'Markt',
      kicker: island ? `${island.name} · Handel` : 'Handel',
      body: `
        <p class="lead">„${esc(npc.greeting)}“</p>
        <h3>Ware</h3>
        <div class="shop-grid">${buyRows || '<div class="empty-note">Ausverkauft.</div>'}</div>
        <h3>Deine Beute</h3>
        <div class="shop-grid">${sellRows || '<div class="empty-note">Nichts zu verkaufen. Plündere ein paar Schiffe.</div>'}</div>
        <div class="map-legend"><span>🪙 Gold: <b style="color:var(--gold-bright)">${fmt(s.gold)}</b></span></div>`
    };
  }

  panelShipyard(island) {
    const g = this.game;
    const s = g.state;
    const repairCost = g.repairCost();
    const upgrades = [
      { id: 'cannons', name: 'Kanonen', desc: '+8% Schaden pro Stufe', max: 5 },
      { id: 'hull', name: 'Rumpf', desc: '+40 max. HP pro Stufe', max: 5 },
      { id: 'sails', name: 'Segel', desc: '+4% Tempo pro Stufe', max: 5 }
    ].map((u) => {
      const lvl = s.upgrades[u.id] || 0;
      const cost = g.upgradeCost(u.id);
      return `<div class="skill-node ${lvl >= u.max ? 'maxed' : ''}">
        <div class="sn-head"><span class="sn-name">${u.name}</span><span class="sn-rank">${lvl} / ${u.max}</span></div>
        <div class="sn-desc">${u.desc}</div>
        <button data-act="upgrade" data-upgrade="${u.id}" ${lvl >= u.max || s.gold < cost ? 'disabled' : ''}>
          ${lvl >= u.max ? 'Maximal' : `Aufrüsten · ${fmt(cost)} 🪙`}
        </button></div>`;
    }).join('');
    const ships = g.data.ships.playerShips.map((ship) => {
      const current = s.shipId === ship.id;
      const owned = s.ownedShips.includes(ship.id);
      return `<div class="ship-card ${current ? 'current' : owned ? 'owned' : ''}">
        <h4>${esc(ship.name)}</h4>
        <div class="sc-class">${ship.class}${current ? ' · aktiv' : owned ? ' · im Besitz' : ''}</div>
        <div class="ship-stats">
          <span>Hülle <b>${ship.hp}</b></span><span>Tempo <b>${ship.speed}</b></span>
          <span>Kanonen <b>${ship.cannons}</b></span><span>Crew <b>${ship.crew}</b></span>
        </div>
        <button data-act="${owned ? 'equip-ship' : 'buy-ship'}" data-ship="${ship.id}"
          ${current || (!owned && s.gold < ship.price) ? 'disabled' : ''}>
          ${current ? 'Aktives Schiff' : owned ? 'Übernehmen' : `${fmt(ship.price)} 🪙 kaufen`}
        </button>
      </div>`;
    }).join('');
    return {
      title: 'Werft',
      kicker: island ? island.name : 'Hafen',
      body: `
        <p class="lead">„Rumpf hält. Segel halten. Der Rest ist Glaube.“</p>
        <h3>Instandsetzung</h3>
        <div class="item-row">
          <span class="i-ico">🔧</span>
          <div class="i-main"><div class="i-name">Hülle reparieren</div>
            <div class="i-sub">${Math.round(s.hp)} / ${g.maxHp()} HP · Kosten ${fmt(repairCost)} 🪙</div></div>
          <button data-act="repair" ${repairCost <= 0 || s.gold < repairCost ? 'disabled' : ''}>Reparieren</button>
        </div>
        <h3>Aufrüstung</h3>
        <div class="skill-cols">${upgrades.split('</div><div').join('')}</div>
        <h3>Schiffe</h3>
        <div class="ship-grid">${ships}</div>`
    };
  }

  panelTavern(island) {
    const g = this.game;
    const s = g.state;
    const missing = g.maxHp() - s.hp;
    const cost = Math.max(0, Math.round(missing * 0.6));
    const rumors = [
      'Im Wrackgrab liegt mehr Gold als in jeder Bank. Und mehr Flüche.',
      'Die Marine zahlt Kopfgeld auf dich. Die Höhe ist ein Kompliment.',
      'Der Leviathan schläft nie. Er wartet nur.',
      'Eine Frucht im Tempel soll den Wind selbst beugen.',
      'Rabenfels kauft alles. Wirklich alles.'
    ];
    const rumor = rumors[Math.floor(Math.random() * rumors.length)];
    return {
      title: 'Taverne',
      kicker: island ? island.name : 'Hafen',
      body: `
        <p class="lead">„Setz dich. Die See draußen wartet lange genug.“</p>
        <div class="item-row">
          <span class="i-ico">🍺</span>
          <div class="i-main"><div class="i-name">Runde für die Crew</div>
            <div class="i-sub">Heilt vollständig · ${fmt(cost)} 🪙</div></div>
          <button data-act="heal" ${cost <= 0 || s.gold < cost ? 'disabled' : ''}>Bezahlen</button>
        </div>
        <div class="item-row" style="margin-top:8px">
          <span class="i-ico">🍾</span>
          <div class="i-main"><div class="i-name">Rum kaufen</div>
            <div class="i-sub">Heilt 25 HP auf See · ${fmt(g.buyPrice({ value: 14 }, 'tavern'))} 🪙</div></div>
          <button data-act="buy" data-item="rum" data-service="tavern" ${s.gold < g.buyPrice({ value: 14 }, 'tavern') ? 'disabled' : ''}>Kaufen</button>
        </div>
        <h3>Gerücht des Abends</h3>
        <p class="lead">„${esc(rumor)}“</p>`
    };
  }

  panelShrine(island) {
    const g = this.game;
    const s = g.state;
    const fruit = g.fruitDef();
    const cards = g.data.fruits.map((f) => {
      const active = s.fruitId === f.id;
      return `<div class="quest-card ${active ? 'active' : ''}">
        <div class="qc-head"><span class="qc-name" style="color:${f.color}">${esc(f.name)}</span>
          <span class="qc-tag">${f.element}</span></div>
        <div class="qc-text">${esc(f.desc)}<br><b style="color:var(--gold-bright)">Passiv:</b> ${esc(f.passive)}</div>
        <div class="qc-reward">${f.abilities.map((a) => `${ABILITY_ICONS[a.id] || '✦'} ${a.name}`).join(' · ')}</div>
        <button data-act="eat-fruit" data-fruit="${f.id}" ${active || s.gold < 900 ? 'disabled' : ''}>
          ${active ? 'Aktive Frucht' : 'Frucht essen · 900 🪙'}</button>
      </div>`;
    }).join('');
    return {
      title: 'Urkraft-Schrein',
      kicker: island ? island.name : 'Tempel',
      body: `
        <p class="lead">„Die Frucht wählt dich. Nicht umgekehrt.“</p>
        <p>Aktive Frucht: <b style="color:${fruit?.color || '#fff'}">${esc(fruit?.name || 'keine')}</b> · Gold: <b>${fmt(s.gold)}</b></p>
        <div class="quest-grid">${cards}</div>`
    };
  }

  panelQuests(island) {
    const g = this.game;
    const s = g.state;
    const available = g.data.quests.filter((q) => (!island || q.giver === island.id) && !s.quests.some((a) => a.id === q.id));
    const active = s.quests.filter((q) => !q.done);
    const done = s.quests.filter((q) => q.done);
    const qCard = (def, state, kind) => {
      const prog = state ? Math.min(state.progress, def.count) : 0;
      return `<div class="quest-card ${state?.done ? 'done' : state ? 'active' : ''}">
        <div class="qc-head"><span class="qc-name">${esc(def.name)}</span><span class="qc-tag">${def.type === 'kill' ? 'Kampf' : def.type === 'collect' ? 'Sammeln' : 'Reise'}</span></div>
        <div class="qc-text">${esc(def.text)}</div>
        <div class="qc-reward">+${fmt(def.xp)} XP · +${fmt(def.gold)} 🪙${def.items.map((i) => ` · ${i.count}× ${g.itemDef(i.id)?.name || i.id}`).join('')}</div>
        ${state ? `<div class="q-progress" style="margin-bottom:8px"><i style="--p:${(prog / def.count) * 100}%"></i><b>${prog} / ${def.count}</b></div>` : ''}
        ${kind === 'available' ? `<button data-act="accept-quest" data-quest="${def.id}">Annehmen</button>` : ''}
        ${kind === 'active' ? `<button data-act="abandon-quest" data-quest="${def.id}">Abbrechen</button>` : ''}
        ${kind === 'done' ? `<button disabled>Abgeschlossen</button>` : ''}
      </div>`;
    };
    return {
      title: 'Auftragsbrett',
      kicker: island ? island.name : 'Hafen',
      body: `
        <p class="lead">„Papier, Nägel, Hoffnung. Nimm dir was.“</p>
        <h3>Verfügbar</h3>
        <div class="quest-grid">${available.length ? available.map((q) => qCard(q, null, 'available')).join('') : '<div class="empty-note">Hier gibt es gerade nichts Neues.</div>'}</div>
        <h3>Aktiv</h3>
        <div class="quest-grid">${active.length ? active.map((a) => qCard(g.data.quests.find((q) => q.id === a.id), a, 'active')).join('') : '<div class="empty-note">Kein Auftrag aktiv. Die See ist geduldig.</div>'}</div>
        ${done.length ? `<h3>Abgeschlossen</h3><div class="quest-grid">${done.map((a) => qCard(g.data.quests.find((q) => q.id === a.id), a, 'done')).join('')}</div>` : ''}`
    };
  }

  panelInventory() {
    const g = this.game;
    const s = g.state;
    const entries = Object.entries(s.inventory).filter(([, c]) => c > 0);
    const cells = entries.map(([id, count]) => {
      const item = g.itemDef(id);
      if (!item) return '';
      return `<div class="inv-cell rarity-${item.rarity}" style="border-color:${RARITY[item.rarity]?.color}44">
        <div class="ic-top"><span>${RARITY[item.rarity]?.label || ''}</span><span>×${count}</span></div>
        <div class="ic-icon">${item.icon}</div>
        <div class="ic-name">${esc(item.name)}</div>
        <div class="ic-desc">${esc(item.desc)}</div>
        <div class="ic-actions">
          ${item.type === 'consumable' ? `<button data-act="use-item" data-item="${id}">Benutzen</button>` : ''}
          ${item.type === 'fruit' ? `<button data-act="eat-item" data-item="${id}">Essen</button>` : ''}
          ${item.type !== 'fruit' ? `<button data-act="drop-item" data-item="${id}">Ablegen</button>` : ''}
        </div>
      </div>`;
    }).join('');
    return {
      title: 'Inventar',
      kicker: 'Laderaum',
      body: `<div class="inv-grid">${cells || '<div class="empty-note">Der Laderaum ist leer. Das Meer ist voll.</div>'}</div>
      <h3>Schiff</h3>
      <div class="ship-stats" style="max-width:340px">
        <span>Hülle <b>${Math.round(s.hp)} / ${g.maxHp()}</b></span><span>Tempo <b>${g.shipDef().speed}</b></span>
        <span>Kanonen <b>${g.shipDef().cannons}</b></span><span>Crew <b>${g.shipDef().crew}</b></span>
      </div>`
    };
  }

  panelSkills() {
    const g = this.game;
    const s = g.state;
    const info = levelFromXp(s.xp);
    const cols = g.data.skills.map((tree) => `
      <div class="skill-col">
        <h4 style="color:${tree.color}">${tree.name}</h4>
        ${tree.nodes.map((node) => {
          const rank = s.skills[node.id] || 0;
          return `<div class="skill-node ${rank >= node.max ? 'maxed' : ''}">
            <div class="sn-head"><span class="sn-name">${node.name}</span><span class="sn-rank">${rank} / ${node.max}</span></div>
            <div class="sn-desc">${node.desc}</div>
            <button data-act="add-skill" data-node="${node.id}" ${rank >= node.max || s.skillPoints <= 0 ? 'disabled' : ''}>
              ${rank >= node.max ? 'Maximal' : 'Punkt investieren'}
            </button></div>`;
        }).join('')}
      </div>`).join('');
    return {
      title: 'Fähigkeiten',
      kicker: `Level ${info.level} · ${s.skillPoints} Punkte`,
      body: `<div class="skill-points">Verfügbare Skillpunkte: <b>${s.skillPoints}</b> · Nächster Punkt bei Level ${info.level + 1}</div>
        <div class="skill-cols">${cols}</div>
        <h3>Urkraft</h3>
        <p>${esc(g.fruitDef()?.name || 'Keine')} – ${esc(g.fruitDef()?.passive || '')}</p>`
    };
  }

  panelMap() {
    return {
      title: 'Seekarte',
      kicker: 'Die Weite',
      body: `<div class="map-holder"><canvas id="big-map" width="1000" height="1000"></canvas></div>
        <div class="map-legend">
          <span><i style="background:#e8c87a"></i>Insel</span>
          <span><i style="background:#ff8f7a"></i>Feind</span>
          <span><i style="background:#c08cff"></i>Boss</span>
          <span><i style="background:#54c7b5"></i>Spieler</span>
          <span>Klick auf die Karte setzt einen Kurs.</span>
        </div>`,
      after: () => this.wireBigMap()
    };
  }

  wireBigMap() {
    const canvas = document.getElementById('big-map');
    if (!canvas) return;
    this.drawBigMap(canvas);
    canvas.addEventListener('click', (e) => {
      const rect = canvas.getBoundingClientRect();
      const x = ((e.clientX - rect.left) / rect.width) * 2 * 1500 - 1500;
      const z = ((e.clientY - rect.top) / rect.height) * 2 * 1500 - 1500;
      this.game.setWaypoint(x, z);
      this.drawBigMap(canvas);
    });
  }

  drawBigMap(canvas) {
    const g = this.game;
    const ctx = canvas.getContext('2d');
    const S = canvas.width;
    const toMap = (x, z) => [((x + 1500) / 3000) * S, ((z + 1500) / 3000) * S];
    const grd = ctx.createLinearGradient(0, 0, S, S);
    grd.addColorStop(0, '#0a2c38');
    grd.addColorStop(1, '#051820');
    ctx.fillStyle = grd;
    ctx.fillRect(0, 0, S, S);
    // grid
    ctx.strokeStyle = 'rgba(232, 200, 122, 0.08)';
    ctx.lineWidth = 1;
    for (let i = 1; i < 10; i++) {
      ctx.beginPath();
      ctx.moveTo((S / 10) * i, 0); ctx.lineTo((S / 10) * i, S);
      ctx.moveTo(0, (S / 10) * i); ctx.lineTo(S, (S / 10) * i);
      ctx.stroke();
    }
    ctx.strokeStyle = 'rgba(232, 200, 122, 0.18)';
    ctx.beginPath();
    ctx.arc(S / 2, S / 2, (1500 / 3000) * S, 0, Math.PI * 2);
    ctx.stroke();

    for (const isl of g.data.islands) {
      const [x, y] = toMap(isl.x, isl.z);
      ctx.beginPath();
      ctx.arc(x, y, (isl.radius / 3000) * S + 6, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(232, 200, 122, 0.2)';
      ctx.fill();
      ctx.strokeStyle = 'rgba(232, 200, 122, 0.7)';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = '#f4ecd9';
      ctx.font = '17px Georgia, serif';
      ctx.textAlign = 'center';
      ctx.fillText(isl.name, x, y - 16);
      ctx.fillStyle = 'rgba(147, 174, 180, 0.9)';
      ctx.font = '12px sans-serif';
      ctx.fillText(`Lv ${isl.level}`, x, y + 18);
    }
    for (const n of g.getNpcs()) {
      if (!n.alive) continue;
      const [x, y] = toMap(n.x, n.z);
      ctx.beginPath();
      ctx.arc(x, y, n.boss ? 9 : 5, 0, Math.PI * 2);
      ctx.fillStyle = n.boss ? '#c08cff' : '#ff8f7a';
      ctx.fill();
    }
    if (g.net?.connected) {
      for (const p of g.net.players.values()) {
        if (p.id === g.net.id) continue;
        const [x, y] = toMap(p.x, p.z);
        ctx.beginPath();
        ctx.arc(x, y, 5, 0, Math.PI * 2);
        ctx.fillStyle = '#54c7b5';
        ctx.fill();
      }
    }
    const [px, py] = toMap(g.pos.x, g.pos.z);
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(-g.rot + Math.PI);
    ctx.beginPath();
    ctx.moveTo(0, -14);
    ctx.lineTo(9, 10);
    ctx.lineTo(0, 5);
    ctx.lineTo(-9, 10);
    ctx.closePath();
    ctx.fillStyle = '#fff';
    ctx.fill();
    ctx.restore();
    if (g.waypoint) {
      const [x, y] = toMap(g.waypoint.x, g.waypoint.z);
      ctx.strokeStyle = '#e8c87a';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(x, y, 10, 0, Math.PI * 2);
      ctx.moveTo(x - 14, y); ctx.lineTo(x + 14, y);
      ctx.moveTo(x, y - 14); ctx.lineTo(x, y + 14);
      ctx.stroke();
    }
  }

  panelMenu() {
    const g = this.game;
    const s = g.state;
    const info = levelFromXp(s.xp);
    return {
      title: 'Logbuch',
      kicker: 'Pause · Einstellungen',
      body: `
        <p class="lead">Kapitän ${esc(s.name)} · ${FACTIONS[s.faction]?.label} · Level ${info.level}</p>
        <div class="service-grid">
          <button class="service-btn" data-act="open" data-panel="controls"><b>🎮 Steuerung</b><span>Tastatur, Maus und Touch.</span></button>
          <button class="service-btn" data-act="open" data-panel="inventory"><b>🎒 Inventar</b><span>Laderaum und Ausrüstung.</span></button>
          <button class="service-btn" data-act="open" data-panel="skills"><b>✦ Fähigkeiten</b><span>Skillpunkte verteilen.</span></button>
          <button class="service-btn" data-act="open" data-panel="account"><b>☁️ Konto</b><span>Cloud-Save und Anmeldung.</span></button>
          <button class="service-btn" data-act="toggle-audio"><b>${g.audio.enabled ? '🔊' : '🔇'} Ton</b><span>Prozedurale Sounds an/aus.</span></button>
          <button class="service-btn" data-act="save"><b>💾 Speichern</b><span>Spielstand lokal sichern.</span></button>
          <button class="service-btn" data-act="reset"><b>🗑️ Neuer Spielstand</b><span>Löscht den lokalen Fortschritt.</span></button>
          <button class="service-btn" data-act="reload"><b>⏏️ Zur Startseite</b><span>Zurück zur Charakterwahl.</span></button>
        </div>
        <h3>See-Status</h3>
        <p>${g.net?.connected ? `Online · ${g.net.online} Kapitäne auf See · Server verbunden` : 'Offline-Modus · Einzelspieler'}<br>
        Gold ${fmt(s.gold)} · Kopfgeld ${fmt(s.bounty)} · Aufträge ${s.quests.filter((q) => !q.done).length} aktiv</p>`
    };
  }

  panelControls() {
    return {
      title: 'Steuerung',
      kicker: 'Handbuch',
      body: `
        <div class="skill-cols">
          <div class="skill-col"><h4>Am Ruder</h4>
            <p><kbd>W</kbd>/<kbd>S</kbd> Segel setzen &amp; bremsen<br>
            <kbd>A</kbd>/<kbd>D</kbd> Ruder<br>
            <kbd>Shift</kbd> Boost<br>
            <kbd>Leertaste</kbd> Breitseite<br>
            <kbd>F</kbd> Anlegen / Interagieren<br>
            <kbd>1</kbd>–<kbd>3</kbd> Urkraft-Fähigkeiten</p></div>
          <div class="skill-col"><h4>An Bord</h4>
            <p><kbd>M</kbd> Seekarte<br>
            <kbd>Tab</kbd> Inventar<br>
            <kbd>K</kbd> Fähigkeiten<br>
            <kbd>Esc</kbd> Logbuch / schließen<br>
            <kbd>Enter</kbd> Chat<br>
            Mausrad: Kamera-Zoom</p></div>
          <div class="skill-col"><h4>Touch</h4>
            <p>Linker Joystick: Segel &amp; Ruder<br>
            Rechte Buttons: Feuer, Anlegen, Fähigkeiten<br>
            Karte &amp; Inventar oben<br>
            Gerät quer halten für die volle See.</p></div>
        </div>`
    };
  }

  panelAccount() {
    const net = this.game.net;
    const logged = Boolean(net?.token && net?.accountName);
    const body = logged ? `
      <p class="lead">Angemeldet als <b>${esc(net.accountName)}</b>.</p>
      <p class="status-line ok">Cloud-Save aktiv. Lokaler Fortschritt bleibt erhalten.</p>
      <div class="service-grid" style="margin-top:12px">
        <button class="service-btn" data-act="cloud-save"><b>☁️ In Cloud speichern</b><span>Überträgt den aktuellen Spielstand.</span></button>
        <button class="service-btn" data-act="cloud-load"><b>⬇️ Aus Cloud laden</b><span>Ersetzt den lokalen Spielstand.</span></button>
        <button class="service-btn" data-act="logout"><b>🚪 Abmelden</b><span>Token wird entfernt.</span></button>
      </div>
      <p class="status-line" id="account-status"></p>` : `
      <p class="lead">Ein Konto ist optional. Es ermöglicht Cloud-Saves zwischen Geräten.</p>
      <div class="account-form">
        <input id="acc-name" placeholder="Kapitänsname" maxlength="16" autocomplete="username" />
        <input id="acc-pass" type="password" placeholder="Passwort (min. 4 Zeichen)" autocomplete="current-password" />
        <div class="row">
          <button data-act="account-login">Anmelden</button>
          <button data-act="account-register">Konto erstellen</button>
        </div>
      </div>
      <p class="status-line" id="account-status">Ohne Konto wird der Fortschritt nur lokal im Browser gespeichert.</p>`;
    return { title: 'Konto & Cloud', kicker: 'Optional', body };
  }

  setAccountStatus(text, kind = '') {
    const el = document.getElementById('account-status');
    if (el) { el.textContent = text; el.className = `status-line ${kind}`; }
  }

  /* ------------------------------ actions ------------------------------ */

  handleAction(act, data) {
    const g = this.game;
    switch (act) {
      case 'service': this.openPanel(data.service, this.panel?.island); break;
      case 'undock': g.undock(); this.closePanel(); break;
      case 'set-waypoint': {
        const isl = g.data.islands.find((i) => i.id === data.island);
        if (isl) { g.setWaypoint(isl.x, isl.z); this.toast(`Kurs gesetzt: ${isl.name}`, 'gold', '🧭'); }
        this.closePanel();
        break;
      }
      case 'buy': {
        const item = g.itemDef(data.item);
        if (!item) break;
        const price = g.buyPrice(item, data.service);
        if (g.buyItem(item, price)) this.refresh();
        break;
      }
      case 'sell': {
        const item = g.itemDef(data.item);
        if (item) g.sellItem(item, Number(data.count) || 1);
        this.refresh();
        break;
      }
      case 'repair':
        g.repairShip();
        this.refresh();
        break;
      case 'upgrade':
        g.upgradeShip(data.upgrade);
        this.refresh();
        break;
      case 'buy-ship':
        g.buyShip(data.ship);
        this.refresh();
        break;
      case 'equip-ship':
        g.equipShip(data.ship);
        this.refresh();
        break;
      case 'heal':
        g.healAtTavern();
        this.refresh();
        break;
      case 'eat-fruit':
        g.eatFruit(data.fruit);
        this.refresh();
        break;
      case 'accept-quest':
        g.acceptQuest(data.quest);
        this.refresh();
        break;
      case 'abandon-quest':
        g.abandonQuest(data.quest);
        this.refresh();
        break;
      case 'use-item':
        g.useItem(data.item);
        this.refresh();
        break;
      case 'eat-item':
        g.eatFruitItem(data.item);
        this.refresh();
        break;
      case 'drop-item':
        g.dropItem(data.item);
        this.refresh();
        break;
      case 'add-skill':
        g.addSkill(data.node);
        this.refresh();
        break;
      case 'open':
        this.openPanel(data.panel, this.panel?.island);
        break;
      case 'toggle-audio':
        g.audio.setEnabled(!g.audio.enabled);
        this.refresh();
        break;
      case 'save':
        g.save();
        this.toast('Spielstand gespeichert.', 'good', '💾');
        break;
      case 'reset':
        g.resetSave();
        break;
      case 'reload':
        location.reload();
        break;
      case 'account-login':
      case 'account-register': {
        const name = document.getElementById('acc-name')?.value || '';
        const pass = document.getElementById('acc-pass')?.value || '';
        g.accountAction(act === 'account-login' ? 'login' : 'register', name, pass);
        break;
      }
      case 'cloud-save':
        g.cloudSave();
        break;
      case 'cloud-load':
        g.cloudLoad();
        break;
      case 'logout':
        g.net.logout();
        this.refresh();
        break;
    }
  }
}

import * as THREE from 'three';
import { World, waveHeight, factionColor } from './world.js';
import { buildShip, buildCaptain, buildCrate, buildProjectile } from './ship.js';
import { Effects } from './effects.js';
import { Audio } from './audio.js';
import { UI, FACTIONS } from './ui.js';
import { SeaSim } from './shared/sim.js';
import {
  levelFromXp, xpForLevel, clampSea, dist, cannonDamage, RARITY
} from './shared/rules.js';

const SAVE_KEY = 'kaperfahrt.save.v1';
const TAU = Math.PI * 2;

function approach(current, target, delta) {
  if (current < target) return Math.min(target, current + delta);
  return Math.max(target, current - delta);
}

function moveTowardAngle(current, target, maxDelta) {
  let d = ((target - current + Math.PI) % TAU + TAU) % TAU - Math.PI;
  return current + Math.max(-maxDelta, Math.min(maxDelta, d));
}

export class Game {
  constructor(data, net) {
    this.data = data;
    this.net = net;
    this.state = null;
    this.loadedProfile = null;
    this.time = 0;
    this.lastFrame = 0;
    this.pos = { x: 0, z: 70 };
    this.rot = 0;
    this.speed = 0;
    this.throttle = 0;
    this.rudder = 0;
    this.boostEnergy = 100;
    this.boosting = false;
    this.abilityReady = [0, 0, 0];
    this.shieldUntil = 0;
    this.boostUntil = 0;
    this.hiddenUntil = 0;
    this.waypoint = null;
    this.waypointMesh = null;
    this.nearIsland = null;
    this.dockedIsland = null;
    this.panelOpen = false;
    this.dead = false;
    this.respawnAt = 0;
    this.zoom = 0;
    this.cameraShake = 0;
    this.keys = new Set();
    this.touch = { active: false, x: 0, y: 0 };
    this.sim = null;
    this.npcMeshes = new Map();
    this.lootMeshes = new Map();
    this.claiming = new Set();
    this.shots = [];
    this.fireCooldown = 0;
    this.remoteMeshes = new Map();
    this.lastSave = 0;
    this.levelCheck = 1;
    this.hudTick = 0;
    this.acc = 0;
    this.offlineFallback = false;
    this.questToastShown = new Set();
  }

  /* ------------------------------- boot ------------------------------- */

  init() {
    this.scene = new THREE.Scene();
    this.scene.fog = new THREE.FogExp2(0xbfe7ea, 0.00075);

    this.camera = new THREE.PerspectiveCamera(56, window.innerWidth / window.innerHeight, 0.5, 5000);
    this.camera.position.set(120, 60, 210);

    this.renderer = new THREE.WebGLRenderer({
      canvas: document.getElementById('scene'),
      antialias: true,
      powerPreference: 'high-performance'
    });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.6));
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.05;
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;

    this.world = new World(this.scene, this.data.islands);
    this.effects = new Effects(this.scene);
    this.audio = new Audio();
    this.ui = new UI(this);

    this.lookAt = new THREE.Vector3(0, 12, 0);
    this.cameraTarget = new THREE.Vector3(0, 10, 0);
    this.smoothCam = new THREE.Vector3(120, 60, 210);

    this.bindInput();
    this.bindNet();
    this.setupJoystick();

    window.addEventListener('resize', () => this.resize());
    this.resize();
    this.loadedProfile = this.readSave();
    this.ui.showStart(Boolean(this.loadedProfile));

    this.clock = new THREE.Clock();
    this.renderer.setAnimationLoop(() => this.frame());
  }

  resize() {
    this.camera.aspect = window.innerWidth / window.innerHeight;
    this.camera.updateProjectionMatrix();
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.6));
    this.renderer.setSize(window.innerWidth, window.innerHeight);
  }

  readSave() {
    try {
      const raw = localStorage.getItem(SAVE_KEY);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      return parsed && parsed.version === 1 ? parsed : null;
    } catch { return null; }
  }

  save() {
    if (!this.state) return;
    const s = this.state;
    const data = {
      version: 1,
      name: s.name,
      faction: s.faction,
      shipId: s.shipId,
      fruitId: s.fruitId,
      xp: s.xp,
      gold: s.gold,
      bounty: s.bounty,
      hp: Math.round(s.hp),
      skillPoints: s.skillPoints,
      skills: s.skills,
      inventory: s.inventory,
      quests: s.quests,
      ownedShips: s.ownedShips,
      upgrades: s.upgrades,
      pos: { x: this.pos.x, z: this.pos.z },
      rot: this.rot,
      playtime: s.playtime,
      savedAt: Date.now()
    };
    try { localStorage.setItem(SAVE_KEY, JSON.stringify(data)); } catch {}
    this.loadedProfile = data;
  }

  resetSave() {
    if (!confirm('Wirklich einen neuen Spielstand beginnen? Der lokale Fortschritt geht verloren.')) return;
    localStorage.removeItem(SAVE_KEY);
    location.reload();
  }

  /* ------------------------------- input ------------------------------ */

  bindInput() {
    const isTyping = () => {
      const el = document.activeElement;
      return el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA');
    };
    window.addEventListener('keydown', (e) => {
      if (isTyping()) {
        if (e.key === 'Escape') document.activeElement.blur();
        return;
      }
      const k = e.key.toLowerCase();
      if ([' ', 'tab', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright'].includes(k)) e.preventDefault();
      if (e.repeat) return;
      this.audio.resume();
      this.keys.add(k);
      if (k === ' ') this.fire();
      else if (k === 'f') this.interact();
      else if (k === 'm') this.ui.openMap();
      else if (k === 'tab') this.ui.openInventory();
      else if (k === 'k') this.ui.openSkills();
      else if (k === 'escape') {
        if (this.ui.panel) this.ui.closePanel();
        else this.ui.openMenu();
      } else if (k === 'enter') {
        this.ui.el['chat-input'].focus();
      } else if (['1', '2', '3'].includes(k)) {
        this.useAbility(Number(k) - 1);
      }
    });
    window.addEventListener('keyup', (e) => this.keys.delete(e.key.toLowerCase()));
    window.addEventListener('blur', () => this.keys.clear());
    window.addEventListener('wheel', (e) => {
      this.zoom = Math.max(-12, Math.min(34, this.zoom + e.deltaY * 0.02));
    }, { passive: true });
    window.addEventListener('pointerdown', () => this.audio.resume(), { once: true });
  }

  setupJoystick() {
    const pad = this.ui.el.joystick;
    const knob = this.ui.el['joystick-knob'];
    if (!pad) return;
    let pointerId = null;
    const radius = 44;
    const move = (e) => {
      if (pointerId !== e.pointerId) return;
      const rect = pad.getBoundingClientRect();
      let dx = e.clientX - (rect.left + rect.width / 2);
      let dy = e.clientY - (rect.top + rect.height / 2);
      const len = Math.hypot(dx, dy);
      if (len > radius) { dx = (dx / len) * radius; dy = (dy / len) * radius; }
      knob.style.transform = `translate(${dx}px, ${dy}px)`;
      this.touch.active = true;
      this.touch.x = dx / radius;
      this.touch.y = dy / radius;
    };
    pad.addEventListener('pointerdown', (e) => {
      pointerId = e.pointerId;
      pad.setPointerCapture(e.pointerId);
      this.audio.resume();
      move(e);
    });
    pad.addEventListener('pointermove', move);
    const end = (e) => {
      if (pointerId !== e.pointerId) return;
      pointerId = null;
      knob.style.transform = '';
      this.touch.active = false;
      this.touch.x = 0;
      this.touch.y = 0;
    };
    pad.addEventListener('pointerup', end);
    pad.addEventListener('pointercancel', end);
  }

  /* ------------------------------ start ------------------------------- */

  startNew(draft, name) {
    const clean = (name || '').trim().slice(0, 16) || 'Kapitän';
    const faction = draft.faction || 'pirate';
    const fruit = draft.fruitId || 'kaze';
    const ship = draft.shipId || 'sloop';
    this.state = {
      name: clean,
      faction,
      shipId: ship,
      fruitId: fruit,
      xp: 0,
      gold: 250 + (faction === 'blackmarket' ? 150 : 0),
      bounty: 0,
      hp: 100,
      skillPoints: faction === 'temple' ? 1 : 0,
      skills: {},
      inventory: { rum: 2, kanonenkugel: 12 },
      quests: [],
      ownedShips: [ship],
      upgrades: { cannons: 0, hull: 0, sails: 0 },
      playtime: 0,
      lastLevel: 1
    };
    this.pos = { x: 0, z: 120 };
    this.rot = Math.PI;
    this.state.hp = this.maxHp();
    this.enterWorld();
    this.ui.toast(`Willkommen auf See, ${clean}.`, 'gold', '⚓');
    this.connectMultiplayer();
  }

  loadSave() {
    const profile = this.loadedProfile || this.readSave();
    if (!profile) { this.ui.toast('Kein Spielstand gefunden.', 'danger', '⚠️'); return; }
    this.applyProfile(profile);
    this.enterWorld();
    this.ui.toast(`Willkommen zurück, ${this.state.name}.`, 'gold', '⚓');
    this.connectMultiplayer();
  }

  applyProfile(profile) {
    this.state = {
      name: profile.name || 'Kapitän',
      faction: profile.faction || 'pirate',
      shipId: profile.shipId || 'sloop',
      fruitId: profile.fruitId || 'kaze',
      xp: Math.max(0, profile.xp || 0),
      gold: Math.max(0, profile.gold || 0),
      bounty: Math.max(0, profile.bounty || 0),
      hp: profile.hp || 100,
      skillPoints: Math.max(0, profile.skillPoints || 0),
      skills: profile.skills || {},
      inventory: profile.inventory || {},
      quests: Array.isArray(profile.quests) ? profile.quests : [],
      ownedShips: Array.isArray(profile.ownedShips) && profile.ownedShips.length ? profile.ownedShips : [profile.shipId || 'sloop'],
      upgrades: profile.upgrades || { cannons: 0, hull: 0, sails: 0 },
      playtime: profile.playtime || 0,
      lastLevel: levelFromXp(profile.xp || 0).level
    };
    this.pos = { x: profile.pos?.x ?? 0, z: profile.pos?.z ?? 120 };
    this.rot = profile.rot ?? Math.PI;
    this.state.hp = Math.min(this.state.hp, this.maxHp());
    this.speed = 0;
    this.throttle = 0;
    this.rudder = 0;
  }

  enterWorld() {
    this.ui.hideStart();
    this.ui.renderAbilities();
    this.createPlayerShip();
    this.dead = false;
    this.useOfflineSim();
    this.updateCamera(0.016, true);
  }

  createPlayerShip() {
    if (this.playerMesh) this.scene.remove(this.playerMesh);
    const accent = factionColor(this.state.faction);
    this.playerMesh = buildShip({ shipId: this.state.shipId, faction: this.state.faction, accent });
    this.playerMesh.rotation.order = 'YXZ';
    const captain = buildCaptain({
      coat: new THREE.Color(accent).getHex(),
      hat: 0x17171d
    });
    captain.position.set(0, 4.1, -4.4);
    captain.rotation.y = Math.PI;
    this.playerMesh.add(captain);
    this.playerMesh.userData.captain = captain;
    this.scene.add(this.playerMesh);
  }

  connectMultiplayer() {
    const profile = {
      name: this.state.name,
      faction: this.state.faction,
      ship: this.state.shipId,
      fruit: this.state.fruitId,
      xp: this.state.xp,
      gold: this.state.gold,
      bounty: this.state.bounty,
      skills: this.state.skills,
      x: this.pos.x,
      z: this.pos.z,
      rot: this.rot
    };
    this.net.connect(profile).then((ok) => {
      if (ok) {
        this.ui.chat('System', 'Mit dem Meer verbunden. Andere Kapitäne sind sichtbar.', 'neutral', true);
        this.ui.toast('Online-See verbunden.', 'good', '🌐');
      } else {
        this.offlineFallback = true;
        this.ui.chat('System', 'Kein Server erreichbar – du segelst allein.', 'neutral', true);
        this.ui.toast('Offline-Modus: Einzelspieler.', 'gold', '🧭');
      }
    });
  }

  /* ------------------------------ offline ----------------------------- */

  useOfflineSim() {
    if (this.net?.connected) return;
    if (this.sim) return;
    this.sim = new SeaSim({ islands: this.data.islands, enemies: this.data.ships.enemies });
    this.sim.addPlayer('local', {
      name: this.state.name,
      faction: this.state.faction,
      x: this.pos.x,
      z: this.pos.z,
      rot: this.rot,
      hp: this.state.hp,
      maxHp: this.maxHp()
    });
  }

  goOffline() {
    if (!this.state || this.offlineFallback) return;
    this.offlineFallback = true;
    this.net.disconnect();
    this.sim = null;
    this.clearSeaVisuals();
    this.useOfflineSim();
    this.ui.toast('Verbindung verloren – Einzelspieler aktiv.', 'danger', '📡');
  }

  clearSeaVisuals() {
    for (const [, v] of this.npcMeshes) this.scene.remove(v.group);
    this.npcMeshes.clear();
    for (const [, m] of this.lootMeshes) this.scene.remove(m);
    this.lootMeshes.clear();
    for (const [, m] of this.remoteMeshes) this.scene.remove(m.group);
    this.remoteMeshes.clear();
  }

  /* ------------------------------- net -------------------------------- */

  bindNet() {
    const net = this.net;
    net.on('welcome', (msg) => {
      this.ui.setOnline(msg.online);
      this.syncAll();
    });
    net.on('snapshot', () => {
      this.syncAll();
    });
    net.on('event', (ev) => this.onServerEvent(ev));
    net.on('reward', (reward) => {
      this.applyReward(reward);
      this.ui.toast(`Beute geborgen: +${Math.round(reward.gold)} Gold`, 'gold', '💰');
    });
    net.on('hit', (msg) => {
      if (!this.state) return;
      this.state.hp = Math.max(0, msg.hp);
      this.flashDamage();
      this.audio.hit();
      if (this.state.hp <= 0) this.handleDeath();
    });
    net.on('levelup', (msg) => {
      this.ui.toast(`Level ${msg.level} erreicht! +1 Skillpunkt`, 'gold', '✦');
      this.audio.levelup();
      this.state.skillPoints += 1;
      this.save();
    });
    net.on('chat', (msg) => this.ui.chat(msg.from, msg.text, msg.faction));
    net.on('online', (n) => this.ui.setOnline(n));
    net.on('disconnect', () => this.goOffline());
    net.on('joined', (p) => this.ui.chat('System', `${p.name} hat die See betreten.`, 'neutral', true));
    net.on('left', (id) => {
      const mesh = this.remoteMeshes.get(id);
      if (mesh) { this.scene.remove(mesh.group); this.remoteMeshes.delete(id); }
    });
  }

  syncAll() {
    if (!this.state) return;
    this.syncRemotePlayers();
    this.syncNpcs();
    this.syncLoot();
    this.ui.setOnline(this.net.online);
  }

  syncRemotePlayers() {
    if (!this.net.connected) return;
    const seen = new Set();
    for (const p of this.net.players.values()) {
      if (p.id === this.net.id) continue;
      seen.add(p.id);
      let entry = this.remoteMeshes.get(p.id);
      if (!entry) {
        const group = buildShip({ shipId: p.ship || 'sloop', faction: p.faction || 'pirate', accent: factionColor(p.faction) });
        group.rotation.order = 'YXZ';
        const cap = buildCaptain({ coat: factionColor(p.faction), hat: 0x17171d });
        cap.position.set(0, 4.1, -4.4);
        cap.rotation.y = Math.PI;
        group.add(cap);
        this.scene.add(group);
        entry = { group, x: p.x, z: p.z, rot: p.rot };
        this.remoteMeshes.set(p.id, entry);
      }
      entry.target = p;
    }
    for (const [id, entry] of this.remoteMeshes) {
      if (!seen.has(id)) { this.scene.remove(entry.group); this.remoteMeshes.delete(id); }
    }
  }

  syncNpcs() {
    if (this.net.connected) {
      const seen = new Set();
      for (const n of this.net.npcs.values()) {
        seen.add(n.id);
        this.ensureNpcMesh(n);
        const entry = this.npcMeshes.get(n.id);
        entry.target = n;
      }
      for (const [id, entry] of this.npcMeshes) {
        if (!seen.has(id) && !entry.sinking) this.sinkNpcMesh(id);
      }
    } else if (this.sim) {
      for (const n of this.sim.npcs.values()) {
        this.ensureNpcMesh(n);
        const entry = this.npcMeshes.get(n.id);
        if (n.alive) entry.target = n;
        else if (!entry.sinking) this.sinkNpcMesh(n.id);
      }
    }
  }

  ensureNpcMesh(n) {
    if (this.npcMeshes.has(n.id)) return;
    const def = this.data.ships.enemies.find((e) => e.id === n.defId) || {};
    const accent = factionColor(n.faction);
    const group = buildShip({ shipId: n.ship || 'sloop', faction: n.faction, accent });
    group.rotation.order = 'YXZ';
    if (n.boss) group.scale.setScalar(1.45);
    group.position.set(n.x, 0, n.z);
    group.rotation.y = n.rot;
    this.scene.add(group);
    this.npcMeshes.set(n.id, {
      group,
      x: n.x, z: n.z, rot: n.rot,
      target: n,
      boss: Boolean(n.boss),
      def,
      sinking: false,
      sinkT: 0
    });
  }

  sinkNpcMesh(id) {
    const entry = this.npcMeshes.get(id);
    if (!entry || entry.sinking) return;
    entry.sinking = true;
    entry.sinkT = 0;
    this.effects.explosion(entry.group.position.x, entry.group.position.z);
    this.audio.hit();
    setTimeout(() => {
      this.scene.remove(entry.group);
      this.npcMeshes.delete(id);
    }, 3000);
  }

  syncLoot() {
    const list = this.getLoot();
    const seen = new Set();
    for (const l of list) {
      seen.add(l.id);
      if (!this.lootMeshes.has(l.id)) {
        const crate = buildCrate();
        crate.position.set(l.x, 2, l.z);
        this.scene.add(crate);
        this.lootMeshes.set(l.id, crate);
      }
      if (dist(this.pos.x, this.pos.z, l.x, l.z) < 34 && !this.claiming.has(l.id)) {
        this.claimLoot(l);
      }
    }
    for (const [id, mesh] of this.lootMeshes) {
      if (!seen.has(id)) { this.scene.remove(mesh); this.lootMeshes.delete(id); }
    }
  }

  claimLoot(l) {
    this.claiming.add(l.id);
    if (this.net.connected) {
      this.net.send({ t: 'claim', lootId: l.id });
      setTimeout(() => this.claiming.delete(l.id), 2500);
    } else if (this.sim) {
      const reward = this.sim.claimLoot(l.id, 'local');
      if (reward) {
        this.applyReward(reward);
        this.ui.toast(`Beute geborgen: +${reward.gold} Gold`, 'gold', '💰');
      }
      const mesh = this.lootMeshes.get(l.id);
      if (mesh) { this.scene.remove(mesh); this.lootMeshes.delete(l.id); }
      this.claiming.delete(l.id);
    }
  }

  onServerEvent(ev) {
    if (ev.type === 'shot') {
      if (ev.from) {
        this.spawnCannonball(
          new THREE.Vector3(ev.from.x, 4, ev.from.z),
          new THREE.Vector3(ev.to.x, 3, ev.to.z),
          0.45
        );
        this.effects.muzzle(ev.from.x, 4, ev.from.z);
      }
      if (ev.hostile && dist(this.pos.x, this.pos.z, ev.to.x, ev.to.z) < 40) this.flashDamage();
    } else if (ev.type === 'npcHit') {
      this.effects.ring(ev.x, ev.z, 0xffd28a, 8, 0.4);
    } else if (ev.type === 'sink') {
      const npc = ev.npc || {};
      if (npc.defId) this.progressQuest('kill', npc.defId, 1);
      this.ui.toast(`${npc.name || 'Schiff'} versenkt!`, 'good', '☠️');
      this.state.bounty += Math.round((npc.gold || 30) * 0.25);
      this.audio.cannon();
      if (ev.by === this.net.id) this.save();
    } else if (ev.type === 'spawn') {
      if (ev.npc) this.ensureNpcMesh(ev.npc);
    } else if (ev.type === 'ability') {
      this.effects.ability(ev.x, ev.z, ev.color || 0x7fe7d4);
      this.effects.ring(ev.x, ev.z, ev.color || 0x7fe7d4, 20, 0.8);
    } else if (ev.type === 'lootClaimed') {
      const mesh = this.lootMeshes.get(ev.lootId);
      if (mesh) { this.scene.remove(mesh); this.lootMeshes.delete(ev.lootId); }
    }
  }

  /* ------------------------------ entities ---------------------------- */

  getNpcs() {
    if (this.net?.connected) return [...this.net.npcs.values()];
    if (this.sim) return [...this.sim.npcs.values()];
    return [];
  }

  getLoot() {
    if (this.net?.connected) return [...this.net.loot.values()];
    if (this.sim) return [...this.sim.loot.values()].map((l) => this.sim.publicLoot(l));
    return [];
  }

  /* ------------------------------ combat ------------------------------ */

  fire() {
    if (!this.state || this.panelOpen || this.dead || this.dockedIsland) return;
    const now = this.time;
    if (now < this.fireCooldown) return;
    this.fireCooldown = now + 0.55;
    const npcs = this.getNpcs().filter((n) => n.alive !== false && n.hp > 0);
    let target = null;
    let best = 340;
    for (const n of npcs) {
      const d = dist(this.pos.x, this.pos.z, n.x, n.z);
      if (d < best) { best = d; target = n; }
    }
    const muzzles = this.playerMesh.userData.muzzles;
    const side = target ? (this.localSide(target) >= 0 ? 1 : -1) : 1;
    const candidates = muzzles.filter((m) => m.side === side);
    const muzzle = candidates[Math.floor(Math.random() * candidates.length)] || muzzles[0];
    const worldMuzzle = this.playerMesh.localToWorld(muzzle.pos.clone());
    this.effects.muzzle(worldMuzzle.x, worldMuzzle.y, worldMuzzle.z);
    this.audio.cannon();
    this.cameraShake = 0.5;
    this.recoil = 0.5;

    if (!target) {
      const ahead = new THREE.Vector3(
        this.pos.x + Math.sin(this.rot) * 120,
        1.5,
        this.pos.z + Math.cos(this.rot) * 120
      );
      this.spawnCannonball(worldMuzzle, ahead, 0.7);
      setTimeout(() => this.effects.splash(ahead.x, ahead.z, 1.2), 700);
      return;
    }

    const targetPos = new THREE.Vector3(target.x, 4, target.z);
    this.spawnCannonball(worldMuzzle, targetPos, 0.32);
    setTimeout(() => {
      this.effects.explosion(target.x, target.z);
      this.audio.hit();
    }, 320);

    if (this.net.connected) {
      this.net.send({ t: 'fire', npcId: target.id });
    } else if (this.sim) {
      const def = this.shipDef();
      const dmg = cannonDamage(def.damage * 2.2, this.state.skills, this.state.fruitId === 'magma' ? 0.1 : 0);
      const res = this.sim.damageNpc(target.id, dmg, 'local');
      if (res.sank) {
        this.ui.toast(`${target.name} versenkt!`, 'good', '☠️');
        this.state.bounty += Math.round((target.gold || 30) * 0.25);
        this.progressQuest('kill', target.defId, 1);
        this.save();
      }
    }
  }

  localSide(target) {
    const dx = target.x - this.pos.x;
    const dz = target.z - this.pos.z;
    const rightX = Math.cos(this.rot);
    const rightZ = -Math.sin(this.rot);
    return dx * rightX + dz * rightZ;
  }

  spawnCannonball(from, to, duration) {
    const mesh = buildProjectile();
    mesh.position.copy(from);
    this.scene.add(mesh);
    this.shots.push({ mesh, from: from.clone(), to: to.clone(), t: 0, duration });
  }

  useAbility(index) {
    if (!this.state || this.panelOpen || this.dead) return;
    const fruit = this.fruitDef();
    if (!fruit) return;
    const ability = fruit.abilities[index];
    if (!ability) return;
    const now = performance.now() / 1000;
    if ((this.abilityReady[index] || 0) > now) return;
    this.abilityReady[index] = now + ability.cooldown;
    this.effects.ability(this.pos.x, this.pos.z, new THREE.Color(fruit.color).getHex());
    this.audio.tone(520, 0.25, 'triangle', 0.12, 160);
    this.ui.toast(`${ability.name}`, 'good', '✦');
    if (this.net.connected) this.net.send({ t: 'ability', abilityId: ability.id });
    if (ability.id === 'aufwind') this.boostUntil = this.time + 6;
    if (ability.id === 'glutpanzer') this.shieldUntil = this.time + 8;
    if (ability.id === 'nebelhort') {
      this.state.hp = Math.min(this.maxHp(), this.state.hp + 35);
      this.hiddenUntil = this.time + 6;
    }
    if (ability.id === 'schattenritt') {
      const c = clampSea(this.pos.x + Math.sin(this.rot) * 150, this.pos.z + Math.cos(this.rot) * 150);
      this.effects.explosion(this.pos.x, this.pos.z, 0xb48cff);
      this.pos.x = c.x; this.pos.z = c.z;
      this.effects.explosion(c.x, c.z, 0xb48cff);
    }
    if (this.sim && ability.damage > 0) {
      let hits = 0;
      for (const npc of this.sim.npcs.values()) {
        if (!npc.alive) continue;
        if (dist(this.pos.x, this.pos.z, npc.x, npc.z) <= ability.range) {
          const res = this.sim.damageNpc(npc.id, ability.damage, 'local');
          hits++;
          if (res.sank) {
            this.progressQuest('kill', npc.defId, 1);
            this.state.bounty += Math.round((npc.gold || 30) * 0.25);
          }
          if (hits >= 6) break;
        }
      }
    }
  }

  flashDamage() {
    this.cameraShake = Math.max(this.cameraShake, 0.35);
    document.body.animate(
      [{ boxShadow: 'inset 0 0 120px rgba(217,96,77,0.65)' }, { boxShadow: 'inset 0 0 120px rgba(217,96,77,0)' }],
      { duration: 420, easing: 'ease-out' }
    );
  }

  handleDeath() {
    if (this.dead) return;
    this.dead = true;
    this.respawnAt = this.time + 5;
    this.throttle = 0;
    this.speed = 0;
    this.ui.toast('Über Bord gespült! Die See gibt dich zurück …', 'danger', '🌊');
    this.audio.tone(90, 1.4, 'sine', 0.2, -40);
  }

  respawn() {
    this.dead = false;
    this.state.hp = Math.round(this.maxHp() * 0.7);
    this.state.gold = Math.max(0, Math.round(this.state.gold * 0.9));
    this.pos = { x: 0, z: 140 };
    this.rot = Math.PI;
    this.speed = 0;
    this.throttle = 0;
    if (this.sim) {
      const p = this.sim.players.get('local');
      if (p) { p.hp = this.state.hp; p.alive = true; p.x = this.pos.x; p.z = this.pos.z; }
    }
    this.ui.toast('Zurück in Havenhafen. Die Crew hat dich rausgefischt.', 'gold', '⚓');
    this.save();
  }

  /* ----------------------------- quests ------------------------------- */

  progressQuest(type, target, amount) {
    if (!this.state) return;
    for (const q of this.state.quests) {
      if (q.done) continue;
      const def = this.data.quests.find((d) => d.id === q.id);
      if (!def || def.type !== type || def.target !== target) continue;
      q.progress = Math.min(def.count, q.progress + amount);
      if (q.progress >= def.count) {
        q.done = true;
        this.state.xp += def.xp;
        this.state.gold += def.gold;
        for (const it of def.items) this.addItem(it.id, it.count);
        this.ui.toast(`Auftrag abgeschlossen: ${def.name} (+${def.xp} XP)`, 'gold', '📜');
        this.audio.levelup();
        this.checkLevel();
        this.save();
      } else {
        this.ui.toast(`${def.name}: ${q.progress} / ${def.count}`, '', '📜');
      }
    }
  }

  acceptQuest(id) {
    if (!this.state) return;
    if (this.state.quests.filter((q) => !q.done).length >= 3) {
      this.ui.toast('Maximal 3 aktive Aufträge.', 'danger', '📜');
      return;
    }
    if (this.state.quests.some((q) => q.id === id)) return;
    this.state.quests.push({ id, progress: 0, done: false });
    const def = this.data.quests.find((q) => q.id === id);
    this.ui.toast(`Auftrag angenommen: ${def?.name || id}`, 'good', '📜');
    this.save();
  }

  abandonQuest(id) {
    this.state.quests = this.state.quests.filter((q) => q.id !== id || q.done);
    this.save();
  }

  /* ----------------------------- economy ------------------------------ */

  itemDef(id) { return this.data.items.find((i) => i.id === id); }
  shipDef() { return this.data.ships.playerShips.find((s) => s.id === this.state.shipId) || this.data.ships.playerShips[0]; }
  fruitDef() { return this.data.fruits.find((f) => f.id === this.state.fruitId) || null; }

  maxHp() {
    if (!this.state) return 100;
    const ship = this.data.ships.playerShips.find((s) => s.id === this.state.shipId) || this.data.ships.playerShips[0];
    let hp = ship.hp + 40 * (this.state.upgrades?.hull || 0) + 25 * (this.state.skills?.seemannsblut || 0);
    if (this.state.faction === 'marine') hp = Math.round(hp * 1.15);
    return Math.round(hp);
  }

  buyPrice(item, service) {
    const base = service === 'blackmarket' ? 3.2 : 2.2;
    return Math.round(item.value * base);
  }

  sellPrice(item) {
    let p = item.value;
    if (this.state.faction === 'merchant') p *= 1.2;
    if (this.state.faction === 'pirate') p *= 1.1;
    if (this.state.fruitId === 'yami') p *= 1.15;
    return Math.max(1, Math.round(p));
  }

  addItem(id, count = 1) {
    this.state.inventory[id] = (this.state.inventory[id] || 0) + count;
  }

  buyItem(item, price) {
    if (this.state.gold < price) { this.ui.toast('Nicht genug Gold.', 'danger', '🪙'); this.audio.error(); return false; }
    this.state.gold -= price;
    this.addItem(item.id, 1);
    this.ui.toast(`${item.name} gekauft.`, 'good', item.icon);
    this.audio.pickup();
    this.save();
    return true;
  }

  sellItem(item, count = 1) {
    const have = this.state.inventory[item.id] || 0;
    const n = Math.min(have, count);
    if (n <= 0) return;
    const price = this.sellPrice(item) * n;
    this.state.inventory[item.id] -= n;
    if (this.state.inventory[item.id] <= 0) delete this.state.inventory[item.id];
    this.state.gold += price;
    this.ui.toast(`${n}× ${item.name} für ${price} Gold verkauft.`, 'gold', '🪙');
    this.audio.pickup();
    this.save();
  }

  repairCost() {
    const missing = Math.max(0, this.maxHp() - this.state.hp);
    return Math.round(missing * 0.8);
  }

  repairShip() {
    const cost = this.repairCost();
    if (cost <= 0) return;
    if (this.state.gold < cost) { this.ui.toast('Nicht genug Gold für die Reparatur.', 'danger', '🪙'); return; }
    this.state.gold -= cost;
    this.state.hp = this.maxHp();
    this.ui.toast('Hülle repariert. Die Werft grüßt.', 'good', '🔧');
    this.save();
  }

  upgradeCost(type) {
    const lvl = this.state.upgrades?.[type] || 0;
    return Math.round((240 * Math.pow(lvl + 1, 1.35)) / 10) * 10;
  }

  upgradeShip(type) {
    const lvl = this.state.upgrades?.[type] || 0;
    if (lvl >= 5) return;
    const cost = this.upgradeCost(type);
    if (this.state.gold < cost) { this.ui.toast('Nicht genug Gold.', 'danger', '🪙'); return; }
    this.state.gold -= cost;
    this.state.upgrades[type] = lvl + 1;
    if (type === 'hull') this.state.hp = Math.min(this.maxHp(), this.state.hp + 40);
    this.ui.toast('Schiff aufgerüstet.', 'good', '🔨');
    this.save();
  }

  buyShip(id) {
    const ship = this.data.ships.playerShips.find((s) => s.id === id);
    if (!ship) return;
    if (this.state.gold < ship.price) { this.ui.toast('Nicht genug Gold.', 'danger', '🪙'); return; }
    this.state.gold -= ship.price;
    if (!this.state.ownedShips.includes(id)) this.state.ownedShips.push(id);
    this.equipShip(id);
    this.ui.toast(`${ship.name} gekauft!`, 'gold', '⛵');
    this.save();
  }

  equipShip(id) {
    if (!this.state.ownedShips.includes(id)) return;
    this.state.shipId = id;
    this.createPlayerShip();
    this.state.hp = Math.min(this.state.hp, this.maxHp());
    this.save();
  }

  healAtTavern() {
    const missing = this.maxHp() - this.state.hp;
    const cost = Math.round(missing * 0.6);
    if (missing <= 0) return;
    if (this.state.gold < cost) { this.ui.toast('Nicht genug Gold.', 'danger', '🪙'); return; }
    this.state.gold -= cost;
    this.state.hp = this.maxHp();
    this.ui.toast('Die Crew ist wieder bei Kräften.', 'good', '🍺');
    this.save();
  }

  eatFruit(id) {
    const fruit = this.data.fruits.find((f) => f.id === id);
    if (!fruit) return;
    if (this.state.fruitId === id) return;
    if (this.state.gold < 900) { this.ui.toast('Der Schrein verlangt 900 Gold.', 'danger', '🪙'); return; }
    this.state.gold -= 900;
    this.state.fruitId = id;
    this.abilityReady = [0, 0, 0];
    this.ui.renderAbilities();
    this.ui.toast(`${fruit.name} gegessen. Die Urkraft antwortet.`, 'gold', '✦');
    this.audio.levelup();
    this.save();
  }

  eatFruitItem(itemId) {
    if ((this.state.inventory[itemId] || 0) <= 0) return;
    const options = this.data.fruits.filter((f) => f.id !== this.state.fruitId);
    const fruit = options[Math.floor(Math.random() * options.length)];
    if (!fruit) return;
    this.state.inventory[itemId] -= 1;
    if (this.state.inventory[itemId] <= 0) delete this.state.inventory[itemId];
    this.state.fruitId = fruit.id;
    this.abilityReady = [0, 0, 0];
    this.ui.renderAbilities();
    this.ui.toast(`Urlaubsfrucht gegessen: ${fruit.name}.`, 'gold', '🍍');
    this.audio.levelup();
    this.save();
  }

  useItem(id) {
    if ((this.state.inventory[id] || 0) <= 0) return;
    if (id === 'rum') {
      this.state.inventory[id] -= 1;
      if (this.state.inventory[id] <= 0) delete this.state.inventory[id];
      this.state.hp = Math.min(this.maxHp(), this.state.hp + 25);
      this.ui.toast('Rum getrunken. +25 HP, -1 Würde.', 'good', '🍾');
      this.audio.pickup();
      this.save();
    }
  }

  dropItem(id) {
    if ((this.state.inventory[id] || 0) <= 0) return;
    this.state.inventory[id] -= 1;
    if (this.state.inventory[id] <= 0) delete this.state.inventory[id];
    this.ui.toast('Item über Bord geworfen.', '', '🌊');
    this.save();
  }

  addSkill(nodeId) {
    if (this.state.skillPoints <= 0) return;
    let node = null;
    for (const tree of this.data.skills) {
      const found = tree.nodes.find((n) => n.id === nodeId);
      if (found) { node = found; break; }
    }
    if (!node) return;
    const rank = this.state.skills[nodeId] || 0;
    if (rank >= node.max) return;
    this.state.skills[nodeId] = rank + 1;
    this.state.skillPoints -= 1;
    if (nodeId === 'seemannsblut') this.state.hp = Math.min(this.maxHp(), this.state.hp + 25);
    this.ui.toast(`${node.name} verbessert.`, 'good', '✦');
    this.audio.pickup();
    this.save();
  }

  /* ------------------------------ rewards ----------------------------- */

  applyReward(reward) {
    if (!this.state) return;
    const before = levelFromXp(this.state.xp).level;
    if (typeof reward.xpTotal === 'number') this.state.xp = reward.xpTotal;
    else this.state.xp += Math.round(reward.xp || 0);
    if (typeof reward.goldTotal === 'number') this.state.gold = reward.goldTotal;
    else {
      let gold = reward.gold || 0;
      if (this.state.faction === 'pirate') gold = Math.round(gold * 1.1);
      if (this.state.fruitId === 'yami') gold = Math.round(gold * 1.15);
      this.state.gold += gold;
    }
    for (const d of reward.drops || []) {
      this.addItem(d.id, d.count);
      this.progressQuest('collect', d.id, d.count);
    }
    const after = levelFromXp(this.state.xp).level;
    if (after > before) {
      this.state.skillPoints += after - before;
      this.ui.toast(`Level ${after} erreicht! +${after - before} Skillpunkt`, 'gold', '✦');
      this.audio.levelup();
    }
    this.audio.pickup();
    this.save();
  }

  checkLevel() {
    const info = levelFromXp(this.state.xp);
    if (info.level > this.levelCheck) {
      this.state.skillPoints += info.level - this.levelCheck;
      this.levelCheck = info.level;
    }
  }

  /* ----------------------------- docking ------------------------------ */

  interact() {
    if (!this.state || this.panelOpen) return;
    if (this.dockedIsland) { this.ui.openPanel('harbor', this.dockedIsland); return; }
    if (this.nearIsland) { this.dock(this.nearIsland); return; }
    this.ui.toast('Kein Hafen in Reichweite.', '', '🧭');
  }

  dock(island) {
    this.dockedIsland = island;
    this.throttle = 0;
    this.speed = 0;
    this.rudder = 0;
    const dock = island.dock || { x: island.x, z: island.z + island.radius + 30, angle: 0 };
    this.pos = { x: dock.x, z: dock.z };
    this.rot = dock.angle;
    this.ui.promptDock(island);
    this.ui.openPanel('harbor', island);
    this.progressQuest('visit', island.id, 1);
    this.audio.tone(330, 0.4, 'triangle', 0.1, 120);
    this.save();
  }

  undock() {
    if (!this.dockedIsland) return;
    const island = this.dockedIsland;
    this.dockedIsland = null;
    const dock = island.dock || { x: island.x, z: island.z + island.radius + 30, angle: 0 };
    this.pos = { x: dock.x + Math.sin(dock.angle) * 30, z: dock.z + Math.cos(dock.angle) * 30 };
    this.rot = dock.angle;
    this.speed = 3;
    this.throttle = 0.3;
    this.ui.promptDock(null);
    this.ui.closePanel();
    this.ui.toast('Leinen los!', 'good', '⚓');
  }

  /* ----------------------------- waypoint ----------------------------- */

  setWaypoint(x, z) {
    this.waypoint = { x, z };
    if (this.waypointMesh) this.scene.remove(this.waypointMesh);
    const group = new THREE.Group();
    const beam = new THREE.Mesh(
      new THREE.CylinderGeometry(2.2, 2.2, 90, 8, 1, true),
      new THREE.MeshBasicMaterial({ color: 0xe8c87a, transparent: true, opacity: 0.18, side: THREE.DoubleSide, depthWrite: false })
    );
    beam.position.y = 45;
    group.add(beam);
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(7, 9, 32),
      new THREE.MeshBasicMaterial({ color: 0xffd479, transparent: true, opacity: 0.7, side: THREE.DoubleSide, depthWrite: false })
    );
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 1.5;
    group.add(ring);
    group.position.set(x, 0, z);
    group.userData.ring = ring;
    this.scene.add(group);
    this.waypointMesh = group;
  }

  /* ------------------------------- chat ------------------------------- */

  sendChat(text) {
    if (!text) return;
    if (this.net.connected) this.net.send({ t: 'chat', text });
    else this.ui.chat('Du', text, this.state?.faction || 'neutral');
  }

  /* ------------------------------ account ----------------------------- */

  async accountAction(kind, name, password) {
    if (!this.net) return;
    try {
      this.ui.setAccountStatus('Verbinde …');
      const res = kind === 'login' ? await this.net.login(name, password) : await this.net.register(name, password);
      this.ui.setAccountStatus(`Angemeldet als ${res.name}.`, 'ok');
      this.ui.toast(`Konto ${res.name} bereit.`, 'good', '☁️');
      this.ui.refresh();
    } catch (err) {
      this.ui.setAccountStatus(err.message, 'err');
    }
  }

  async cloudSave() {
    if (!this.net.token) { this.ui.setAccountStatus('Bitte zuerst anmelden.', 'err'); return; }
    try {
      await this.net.saveCloud(this.serialize());
      this.ui.setAccountStatus('Spielstand in der Cloud gespeichert.', 'ok');
      this.ui.toast('Cloud-Save abgeschlossen.', 'good', '☁️');
    } catch (err) {
      this.ui.setAccountStatus(err.message, 'err');
    }
  }

  async cloudLoad() {
    if (!this.net.token) { this.ui.setAccountStatus('Bitte zuerst anmelden.', 'err'); return; }
    try {
      const profile = await this.net.loadCloud();
      if (!profile) { this.ui.setAccountStatus('Kein Cloud-Save vorhanden.', 'err'); return; }
      this.applyProfile(profile);
      this.createPlayerShip();
      this.ui.renderAbilities();
      this.save();
      this.ui.closePanel();
      this.ui.toast('Cloud-Save geladen.', 'good', '☁️');
    } catch (err) {
      this.ui.setAccountStatus(err.message, 'err');
    }
  }

  serialize() {
    return {
      version: 1,
      name: this.state.name,
      faction: this.state.faction,
      shipId: this.state.shipId,
      fruitId: this.state.fruitId,
      xp: this.state.xp,
      gold: this.state.gold,
      bounty: this.state.bounty,
      hp: Math.round(this.state.hp),
      skillPoints: this.state.skillPoints,
      skills: this.state.skills,
      inventory: this.state.inventory,
      quests: this.state.quests,
      ownedShips: this.state.ownedShips,
      upgrades: this.state.upgrades,
      pos: { x: this.pos.x, z: this.pos.z },
      rot: this.rot,
      playtime: this.state.playtime
    };
  }

  /* ------------------------------- frame ------------------------------ */

  frame() {
    const dt = Math.min(0.05, this.clock.getDelta());
    this.time += dt;
    if (!this.state) {
      this.updateMenuCamera(dt);
    } else {
      this.update(dt);
    }
    this.world.update(dt, this.camera, this.time);
    this.effects.update(dt);
    this.renderer.render(this.scene, this.camera);
  }

  updateMenuCamera(dt) {
    const a = this.time * 0.045;
    const target = new THREE.Vector3(Math.sin(a) * 230, 58, Math.cos(a) * 230);
    this.camera.position.lerp(target, 1 - Math.exp(-dt * 0.9));
    this.camera.lookAt(0, 16, 0);
    this.ui.updateHUD(dt);
  }

  update(dt) {
    const s = this.state;
    s.playtime += dt;
    if (this.time - this.lastSave > 20) { this.lastSave = this.time; this.save(); }

    if (this.dead && this.time >= this.respawnAt) this.respawn();

    const controlsLocked = this.panelOpen || this.dead;
    let throttleInput = 0;
    let rudderInput = 0;
    if (!controlsLocked) {
      if (this.keys.has('w') || this.keys.has('arrowup')) throttleInput += 1;
      if (this.keys.has('s') || this.keys.has('arrowdown')) throttleInput -= 0.55;
      if (this.keys.has('a') || this.keys.has('arrowleft')) rudderInput -= 1;
      if (this.keys.has('d') || this.keys.has('arrowright')) rudderInput += 1;
      if (this.touch.active) {
        throttleInput += -this.touch.y;
        rudderInput += this.touch.x;
      }
    }
    throttleInput = Math.max(-1, Math.min(1, throttleInput));
    rudderInput = Math.max(-1, Math.min(1, rudderInput));

    const ship = this.shipDef();
    const sailBonus = 1 + 0.04 * (s.upgrades?.sails || 0) + 0.03 * (s.skills?.sternkunde || 0);
    const maxSpeed = ship.speed * sailBonus;
    const windBoost = this.time < this.boostUntil ? 1.45 : 1;
    const fruitTurn = s.fruitId === 'kaze' ? 1.15 : 1;
    const turnRate = ship.turn * (1 + 0.04 * (s.skills?.windlesen || 0)) * fruitTurn;

    if (this.dockedIsland) {
      this.speed = approach(this.speed, 0, 20 * dt);
      this.throttle = approach(this.throttle, 0, 2 * dt);
    } else {
      if (Math.abs(throttleInput) > 0.02) {
        this.throttle = approach(this.throttle, throttleInput, 0.85 * dt);
      }
      this.rudder = approach(this.rudder, rudderInput, 3.2 * dt);
      const targetSpeed = this.throttle * maxSpeed * windBoost;
      this.speed = approach(this.speed, targetSpeed, (5 + Math.abs(targetSpeed) * 0.4) * dt);
      if (this.recoil > 0) { this.speed -= this.recoil * 0.8; this.recoil = Math.max(0, this.recoil - dt * 2); }
      const speedFactor = Math.min(1, Math.abs(this.speed) / Math.max(4, maxSpeed * 0.5));
      this.rot += this.rudder * turnRate * dt * (0.28 + 0.72 * speedFactor) * Math.sign(this.speed || 1);
      this.rot = (this.rot + TAU) % TAU;
      let nx = this.pos.x + Math.sin(this.rot) * this.speed * dt;
      let nz = this.pos.z + Math.cos(this.rot) * this.speed * dt;
      const clamped = clampSea(nx, nz);
      if (clamped.x !== nx || clamped.z !== nz) this.speed *= 0.3;
      nx = clamped.x; nz = clamped.z;
      // island collision
      for (const isl of this.data.islands) {
        const d = dist(nx, nz, isl.x, isl.z);
        const minD = isl.radius + 6;
        if (d < minD) {
          const a = Math.atan2(nx - isl.x, nz - isl.z);
          nx = isl.x + Math.sin(a) * minD;
          nz = isl.z + Math.cos(a) * minD;
          this.speed *= 0.2;
          this.flashDamage();
        }
      }
      this.pos.x = nx; this.pos.z = nz;
      this.boosting = (this.keys.has('shift') || this.boostUntil > this.time) && this.boostEnergy > 0;
      if (this.boosting) {
        this.boostEnergy = Math.max(0, this.boostEnergy - 18 * dt);
        this.speed += 14 * dt;
      } else {
        this.boostEnergy = Math.min(100, this.boostEnergy + 9 * dt);
      }
    }

    this.fireCooldown = Math.max(0, this.fireCooldown - dt);

    // near island detection
    let near = null;
    let bestD = Infinity;
    for (const isl of this.data.islands) {
      const d = dist(this.pos.x, this.pos.z, isl.x, isl.z);
      if (d < isl.radius + 85 && d < bestD) { bestD = d; near = isl; }
    }
    this.nearIsland = near;
    if (this.dockedIsland) {
      this.ui.promptDock(this.dockedIsland);
      this.ui.el['dock-label'].textContent = `${this.dockedIsland.name} · Hafen öffnen`;
    } else if (near && !this.panelOpen) {
      this.ui.promptDock(near);
    } else {
      this.ui.promptDock(null);
    }

    if (this.sim) {
      this.sim.setPlayerPos('local', this.pos.x, this.pos.z, this.rot, s.hp);
      const events = this.sim.tick(dt);
      for (const ev of events) this.handleSimEvent(ev);
      s.hp = this.sim.players.get('local')?.hp ?? s.hp;
      this.syncNpcs();
      this.syncLoot();
    } else if (this.net.connected) {
      if (!this.hudTick || this.time - this.hudTick > 0.1) {
        this.hudTick = this.time;
        this.net.send({
          t: 'state',
          x: this.pos.x, z: this.pos.z, rot: this.rot,
          hp: s.hp, xp: s.xp, gold: s.gold, bounty: s.bounty
        });
      }
      this.syncRemotePlayers();
      this.syncNpcs();
      this.syncLoot();
    }

    // visuals
    this.updatePlayerVisual(dt);
    this.updateNpcVisuals(dt);
    this.updateLootVisuals(dt);
    this.updateShots(dt);
    this.updateWaypoint();
    this.updateCamera(dt);

    if (s.hp <= 0 && !this.dead) this.handleDeath();
    if (this.time < this.shieldUntil) s.hp = Math.min(this.maxHp(), s.hp + 1.5 * dt);

    this.ui.updateHUD(dt);
    this.ui.updateNameplates(dt);
  }

  handleSimEvent(ev) {
    if (ev.type === 'shot') {
      this.spawnCannonball(
        new THREE.Vector3(ev.from.x, 4, ev.from.z),
        new THREE.Vector3(ev.to.x, 3, ev.to.z),
        0.5
      );
      this.effects.muzzle(ev.from.x, 4, ev.from.z);
      if (ev.hostile && dist(this.pos.x, this.pos.z, ev.to.x, ev.to.z) < 45) this.flashDamage();
    } else if (ev.type === 'npcHit') {
      this.effects.ring(ev.x, ev.z, 0xffd28a, 8, 0.4);
    } else if (ev.type === 'sink') {
      this.ui.toast(`${ev.npc.name} versenkt!`, 'good', '☠️');
      this.state.bounty += Math.round((ev.npc.gold || 30) * 0.25);
      this.progressQuest('kill', ev.npc.defId, 1);
      this.audio.cannon();
      this.save();
    } else if (ev.type === 'playerHit') {
      this.state.hp = ev.hp;
      this.flashDamage();
      this.audio.hit();
    } else if (ev.type === 'respawn') {
      this.pos.x = ev.x; this.pos.z = ev.z;
      this.state.hp = this.maxHp();
      this.ui.toast('Die Crew hat dich zurück an Bord geholt.', 'gold', '⚓');
    }
  }

  updatePlayerVisual(dt) {
    const mesh = this.playerMesh;
    if (!mesh) return;
    const t = this.time;
    const x = this.pos.x;
    const z = this.pos.z;
    const h = waveHeight(x, z, t);
    const fwdX = Math.sin(this.rot);
    const fwdZ = Math.cos(this.rot);
    const hFront = waveHeight(x + fwdX * 8, z + fwdZ * 8, t);
    const hBack = waveHeight(x - fwdX * 8, z - fwdZ * 8, t);
    const hRight = waveHeight(x + Math.cos(this.rot) * 4, z - Math.sin(this.rot) * 4, t);
    const hLeft = waveHeight(x - Math.cos(this.rot) * 4, z + Math.sin(this.rot) * 4, t);
    const pitch = -(hFront - hBack) / 16 * 0.9 - this.speed * 0.0015;
    const roll = (hRight - hLeft) / 8 * 0.7 - this.rudder * 0.16 * Math.min(1, Math.abs(this.speed) / 15);
    mesh.position.set(x, h + 0.3, z);
    mesh.rotation.y = this.rot;
    mesh.rotation.x = THREE.MathUtils.lerp(mesh.rotation.x, pitch, 1 - Math.exp(-dt * 4));
    mesh.rotation.z = THREE.MathUtils.lerp(mesh.rotation.z, roll, 1 - Math.exp(-dt * 4));

    const sails = mesh.userData.sails || [];
    const sailScale = 0.82 + Math.min(1, Math.abs(this.speed) / 26) * 0.18;
    for (const sail of sails) {
      sail.scale.x = THREE.MathUtils.lerp(sail.scale.x, sailScale, 1 - Math.exp(-dt * 3));
      sail.rotation.y = Math.sin(t * 1.4 + sail.position.z) * 0.035 * sailScale;
    }
    const flag = mesh.userData.flag;
    if (flag) flag.rotation.y = Math.sin(t * 3.2) * 0.16 + this.speed * 0.004;
    const captain = mesh.userData.captain;
    if (captain) {
      captain.rotation.y = Math.PI + Math.sin(t * 0.7) * 0.1;
      captain.userData.arms[0].rotation.x = Math.sin(t * 0.8) * 0.08;
    }
  }

  updateNpcVisuals(dt) {
    for (const [id, entry] of this.npcMeshes) {
      const g = entry.group;
      if (entry.sinking) {
        entry.sinkT += dt;
        g.position.y -= dt * 2.2;
        g.rotation.z += dt * 0.45;
        g.rotation.x += dt * 0.12;
        continue;
      }
      const n = entry.target;
      if (!n) continue;
      const blend = 1 - Math.exp(-dt * 8);
      entry.x = THREE.MathUtils.lerp(entry.x, n.x, blend);
      entry.z = THREE.MathUtils.lerp(entry.z, n.z, blend);
      entry.rot = moveTowardAngle(entry.rot, n.rot, dt * 4);
      const h = waveHeight(entry.x, entry.z, this.time);
      g.position.set(entry.x, h + 0.2, entry.z);
      g.rotation.y = entry.rot;
      g.rotation.x = Math.sin(this.time * 0.9 + entry.x) * 0.02;
      g.rotation.z = Math.sin(this.time * 0.7 + entry.z) * 0.03;
      const flag = g.userData.flag;
      if (flag) flag.rotation.y = Math.sin(this.time * 3 + entry.z) * 0.15;
    }
  }

  updateLootVisuals(dt) {
    for (const [, mesh] of this.lootMeshes) {
      mesh.position.y = 2.4 + Math.sin(this.time * 2 + mesh.position.x) * 0.7;
      mesh.rotation.y += dt * 0.8;
      if (mesh.userData.glow) {
        const k = 0.14 + Math.sin(this.time * 3 + mesh.position.z) * 0.05;
        mesh.userData.glow.material.opacity = k;
      }
    }
  }

  updateShots(dt) {
    for (let i = this.shots.length - 1; i >= 0; i--) {
      const s = this.shots[i];
      s.t += dt;
      const k = Math.min(1, s.t / s.duration);
      s.mesh.position.lerpVectors(s.from, s.to, k);
      s.mesh.position.y += Math.sin(k * Math.PI) * 8;
      if (k >= 1) {
        this.scene.remove(s.mesh);
        this.shots.splice(i, 1);
      }
    }
  }

  updateWaypoint() {
    if (!this.waypoint) return;
    if (this.waypointMesh) {
      this.waypointMesh.userData.ring.rotation.z = this.time * 0.6;
      this.waypointMesh.userData.ring.scale.setScalar(1 + Math.sin(this.time * 2) * 0.08);
    }
    if (dist(this.pos.x, this.pos.z, this.waypoint.x, this.waypoint.z) < 40) {
      this.ui.toast('Kurs erreicht.', 'gold', '🧭');
      this.waypoint = null;
      if (this.waypointMesh) { this.scene.remove(this.waypointMesh); this.waypointMesh = null; }
    }
  }

  updateCamera(dt, immediate = false) {
    const distBehind = 34 + this.zoom;
    const height = 15 + this.zoom * 0.35;
    const fwdX = Math.sin(this.rot);
    const fwdZ = Math.cos(this.rot);
    const desired = new THREE.Vector3(
      this.pos.x - fwdX * distBehind,
      height + waveHeight(this.pos.x, this.pos.z, this.time) * 0.4,
      this.pos.z - fwdZ * distBehind
    );
    const look = new THREE.Vector3(
      this.pos.x + fwdX * 16,
      5,
      this.pos.z + fwdZ * 16
    );
    if (immediate) {
      this.camera.position.copy(desired);
      this.lookAt.copy(look);
      this.smoothCam.copy(desired);
    } else {
      const k = 1 - Math.exp(-dt * 2.6);
      this.smoothCam.lerp(desired, k);
      this.lookAt.lerp(look, 1 - Math.exp(-dt * 4));
      this.camera.position.copy(this.smoothCam);
    }
    if (this.cameraShake > 0) {
      const shake = this.cameraShake;
      this.camera.position.x += (Math.random() - 0.5) * shake * 1.4;
      this.camera.position.y += (Math.random() - 0.5) * shake * 0.9;
      this.cameraShake = Math.max(0, this.cameraShake - dt * 2.2);
    }
    this.camera.lookAt(this.lookAt);
  }
}

import { Game } from './game.js';
import { Net } from './net.js';

async function loadJSON(path) {
  const res = await fetch(path, { cache: 'no-cache' });
  if (!res.ok) throw new Error(`${path}: HTTP ${res.status}`);
  return res.json();
}

async function boot() {
  const fill = document.getElementById('loading-fill');
  const text = document.getElementById('loading-text');
  const loading = document.getElementById('loading');
  try {
    text.textContent = 'Seekarten werden gezeichnet …';
    const [islands, items, ships, fruits, skills, quests, npcs] = await Promise.all([
      loadJSON('/data/islands.json'),
      loadJSON('/data/items.json'),
      loadJSON('/data/ships.json'),
      loadJSON('/data/fruits.json'),
      loadJSON('/data/skills.json'),
      loadJSON('/data/quests.json'),
      loadJSON('/data/npcs.json')
    ]);
    fill.style.width = '65%';
    text.textContent = 'Rumpf, Segel und Urkraft …';
    const data = { islands, items, ships, fruits, skills, quests, npcs };
    const net = new Net();
    const game = new Game(data, net);
    window.game = game;
    window.KAPERFAHRT = { version: '0.1.0', data };
    game.init();
    fill.style.width = '100%';
    text.textContent = 'Bereit zum Auslaufen.';
    setTimeout(() => loading.classList.add('done'), 420);
  } catch (err) {
    console.error(err);
    text.textContent = `Fehler beim Laden: ${err.message}`;
    text.style.color = '#ff9d8f';
  }
}

boot();

