/* ------------------------------ responsive ------------------------------ */
@media (max-width: 940px) {
  .start-wrap { grid-template-columns: 1fr; gap: 22px; justify-items: center; }
  .brand { text-align: center; }
  .tagline { margin-left: auto; margin-right: auto; }
  .feature-row { justify-content: center; }
  .editor { width: min(560px, 100%); }
}

@media (max-width: 760px), (pointer: coarse) {
  #hud-top-left { min-width: 0; padding: 7px 10px 7px 7px; gap: 8px; }
  .crest { width: 38px; height: 38px; flex-basis: 38px; font-size: 19px; }
  #hud-name { max-width: 110px; font-size: 14px; }
  .id-row { font-size: 14px; }
  .id-sub { display: none; }
  .bar { height: 9px; }
  .bar b { font-size: 7px; }
  .minimap-wrap { width: 118px; height: 118px; }
  #online-badge { font-size: 9px; padding: 3px 7px; }
  #hud-left { top: calc(74px + var(--safe-t)); width: 220px; gap: 7px; }
  #hud-resources { font-size: 10px; padding: 6px 9px; gap: 10px; }
  #hud-quest { padding: 8px 10px; }
  .q-text { display: none; }
  #quest-name { font-size: 12px; }
  #chat { display: none; }
  #abilities { gap: 6px; }
  .ability { width: 46px; height: 46px; font-size: 18px; border-radius: 10px; }
  #hud-compass { display: none; }
  #hud-bottom { bottom: calc(112px + var(--safe-b)); }
  #hint-bar { display: none; }
  #top-actions { top: calc(10px + var(--safe-t)); gap: 5px; }
  .icon-btn { width: 32px; height: 32px; font-size: 13px; border-radius: 8px; }
  #mobile-controls { display: block; }
  #dock-prompt { bottom: calc(200px + var(--safe-b)); }
  #dock-btn { font-size: 11px; padding: 8px 14px; }
  #toasts { top: calc(62px + var(--safe-t)); }
  .toast { font-size: 10px; padding: 6px 10px; }
  #hud-top-right { top: calc(10px + var(--safe-t)); }
  #start-screen { padding: 14px; align-items: flex-start; }
  .start-wrap { padding-top: 10px; }
  .brand h1 { font-size: 40px; }
  .tagline { font-size: 12px; margin: 10px 0 12px; }
  .feature-row { display: none; }
  .brand-kicker { font-size: 9px; margin-bottom: 8px; }
  .editor { padding: 16px; max-height: none; }
  .editor-head h2 { font-size: 20px; }
  #faction-picker { grid-template-columns: repeat(3, 1fr); }
  #fruit-picker, #ship-picker { grid-template-columns: 1fr; }
  .card { min-height: 0; padding: 8px; }
  .card .c-desc { display: none; }
  .panel { max-height: 92vh; }
  .panel-body { padding: 14px; }
  .skill-cols { grid-template-columns: 1fr; }
  .panel-head { padding: 13px 15px 10px; }
  .panel-head h2 { font-size: 19px; }
  .nameplate { font-size: 8px; }
  .nameplate .np-bar { width: 44px; }
}

@media (max-width: 760px) and (orientation: portrait) {
  #rotate-hint { display: none; }
}

