#hud > * { pointer-events: auto; }
#hud.hidden { display: none; }

#hud-top-left {
  position: absolute; top: calc(14px + var(--safe-t)); left: calc(14px + var(--safe-l));
  display: flex; gap: 12px; align-items: center; padding: 10px 14px 10px 10px; min-width: 290px;
}
.crest {
  width: 48px; height: 48px; flex: 0 0 48px; display: grid; place-items: center; font-size: 24px;
  border-radius: 50%; border: 1px solid var(--gold); color: var(--gold);
  background: radial-gradient(circle at 35% 30%, #143b46, #071b22 70%);
  box-shadow: inset 0 0 18px rgba(232, 200, 122, 0.15);
}
.id-block { flex: 1; min-width: 0; }
.id-row { display: flex; align-items: center; gap: 8px; font-family: Georgia, serif; font-size: 17px; }
#hud-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 150px; }
.level-pill { font-family: "Segoe UI", sans-serif; font-size: 10px; letter-spacing: 0.08em; padding: 2px 7px; border-radius: 999px; background: rgba(232, 200, 122, 0.16); border: 1px solid var(--line); color: var(--gold-bright); }
.id-sub { font-size: 10.5px; color: var(--muted); letter-spacing: 0.05em; margin: 1px 0 6px; }
.id-sub .dot { margin: 0 4px; opacity: 0.5; }
.bar { position: relative; height: 11px; border-radius: 6px; background: rgba(0, 0, 0, 0.45); overflow: hidden; border: 1px solid rgba(255,255,255,0.06); }
.bar + .bar { margin-top: 4px; }
.bar i { display: block; height: 100%; width: 50%; transition: width 0.35s ease; }
.bar.hp i { background: linear-gradient(90deg, #7e2a26, #d9604d 55%, #ff8b74); }
.bar.xp i { background: linear-gradient(90deg, #7c6428, var(--gold)); }
.bar b { position: absolute; inset: 0; display: grid; place-items: center; font-size: 8.5px; font-weight: 600; letter-spacing: 0.05em; text-shadow: 0 1px 2px #000; }

#hud-top-right { position: absolute; top: calc(14px + var(--safe-t)); right: calc(14px + var(--safe-r)); display: flex; flex-direction: column; align-items: flex-end; gap: 8px; }
.minimap-wrap { position: relative; width: 188px; height: 188px; border-radius: 50%; overflow: hidden; padding: 0; }
#minimap { width: 100%; height: 100%; display: block; }
.minimap-n { position: absolute; top: 4px; left: 50%; transform: translateX(-50%); font-size: 9px; color: var(--gold); letter-spacing: 0.2em; }
#online-badge { font-size: 11px; letter-spacing: 0.06em; padding: 5px 10px; color: var(--muted); }
#online-badge span { color: var(--teal-bright); font-weight: 700; }

#hud-left { position: absolute; left: calc(14px + var(--safe-l)); top: calc(96px + var(--safe-t)); width: 292px; display: flex; flex-direction: column; gap: 10px; }
#hud-resources { display: flex; gap: 16px; padding: 8px 12px; font-size: 12px; color: var(--muted); }
#hud-resources b { color: var(--gold-bright); font-size: 13px; }
#hud-quest { padding: 11px 14px; }
.q-head { font-size: 9px; letter-spacing: 0.22em; color: var(--gold); text-transform: uppercase; margin-bottom: 3px; }
#quest-name { font-family: Georgia, serif; font-size: 14px; margin-bottom: 3px; }
.q-text { font-size: 11px; color: var(--muted); line-height: 1.45; }
.q-progress { display: flex; align-items: center; gap: 8px; margin-top: 8px; font-size: 10px; color: var(--gold-bright); }
.q-progress i { flex: 1; height: 3px; background: rgba(255,255,255,0.1); border-radius: 3px; position: relative; }
.q-progress i::after { content: ""; position: absolute; inset: 0; width: var(--p, 0%); background: var(--gold); border-radius: 3px; }

#chat { padding: 8px; display: flex; flex-direction: column; gap: 4px; opacity: 0.92; }
#chat-log { height: 74px; overflow-y: auto; font-size: 11px; line-height: 1.5; scrollbar-width: none; }
#chat-log::-webkit-scrollbar { display: none; }
#chat-log div { color: var(--muted); }
#chat-log b { color: var(--teal-bright); font-weight: 600; }
#chat-log .sys { color: var(--gold); }
#chat-form input {
  width: 100%; border: 0; outline: 0; background: rgba(255, 255, 255, 0.06); color: var(--cream);
  border-radius: 8px; padding: 6px 9px; font-size: 11px; font-family: inherit;
}
#chat-form input::placeholder { color: rgba(147, 174, 180, 0.65); }

#hud-bottom { position: absolute; left: 50%; bottom: calc(28px + var(--safe-b)); transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 10px; }
#abilities { display: flex; gap: 9px; }

